/* ui.js — navegação entre telas, renderização (dashboard, pedidos, clientes, produtos, materiais, estoque, agenda, financeiro, vendas), modais e inicialização do app (PWA/manifest) */

/* ── NAVIGATION ──────────────────────────────────── */
const screenTitles = { dashboard:null, pedidos:'Pedidos', agenda:'Agenda', financeiro:'Financeiro', vendas:'Vendas', produtos:'Produtos', estoque:'Estoque', clientes:'Clientes', ia:'Área IA', assistente:'Assistente', config:'Configurações' };
function navigate(s, param) {
  currentScreen = s;
  document.querySelectorAll('.screen').forEach(el => el.classList.remove('active'));
  document.getElementById('screen-'+s).classList.add('active');
  document.querySelectorAll('.nav-item').forEach(el => {
    el.classList.toggle('active', el.dataset.screen === s);
  });

  const logo   = document.getElementById('topbar-logo');
  const title  = document.getElementById('topbar-title');
  const action = document.getElementById('topbar-action');
  if (s === 'dashboard') {
    logo.style.display = 'block'; title.style.display = 'none';
  } else {
    logo.style.display = 'none'; title.style.display = 'block';
    title.textContent = screenTitles[s];
  }
  action.style.opacity = s==='pedidos' ? '1' : '0';
  action.style.pointerEvents = s==='pedidos' ? 'auto' : 'none';

  document.getElementById('main-content').scrollTop = 0;

  if (s==='dashboard')   renderDashboard();
  if (s==='pedidos')     renderPedidos(param);
  if (s==='agenda')      { renderCalendar(); renderAgendaList(agendaTab); }
  if (s==='financeiro')  renderFinanceiro();
  if (s==='vendas')      renderVendas();
  if (s==='produtos')    renderProdutosScreen();
  if (s==='estoque')     renderEstoqueScreen();
  if (s==='clientes')    renderClientes();
  if (s==='ia')          renderIaScreen();
  if (s==='assistente')  renderAssistenteScreen();

  closeSideNav(); // no-op visually on desktop (side-nav stays fixed open via CSS)
}
function goToScreen(s, filter) { navigate(s, filter); }
function handleBack()    {}
function handleTopAction() { document.getElementById('search-pedidos')?.focus(); }
/* ── SIDE NAV (fixed drawer, overlays content, never pushes layout) ── */
function toggleSideNav() {
  document.getElementById('side-nav').classList.toggle('open');
  document.getElementById('side-nav-overlay').classList.toggle('active');
}
function openSideNav() {
  document.getElementById('side-nav').classList.add('open');
  document.getElementById('side-nav-overlay').classList.add('active');
}
function closeSideNav() {
  document.getElementById('side-nav').classList.remove('open');
  document.getElementById('side-nav-overlay').classList.remove('active');
}
/* ── DASHBOARD ───────────────────────────────────── */
function renderDashboard() {
  renderAvisosEntrega();
  renderMetaCard();
  renderFinResumoDashboard();
  renderAlertasDashboard();
  renderEstoqueBaixoDashboard();

  const pedidos  = load(K.P);
  const today    = todayStr();
  const amanha   = offsetDate(1);
  const d7       = offsetDate(7);
  const atrasados= pedidos.filter(isAtrasado);

  document.getElementById('dash-aberto').textContent   = pedidos.filter(p=>p.status==='Novo').length;
  document.getElementById('dash-prod').textContent     = pedidos.filter(p=>p.status==='Em Produção').length;
  document.getElementById('dash-pronto').textContent   = pedidos.filter(p=>p.status==='Pronto').length;
  document.getElementById('dash-atrasados').textContent= atrasados.length;

  const activeP = p => p.status!=='Entregue' && p.status!=='Cancelado';

  const hoje   = pedidos.filter(p=>p.dataEntrega===today && activeP(p)).sort(sortByDate);
  const ama    = pedidos.filter(p=>p.dataEntrega===amanha && activeP(p)).sort(sortByDate);
  const semana = pedidos.filter(p=>p.dataEntrega>amanha && p.dataEntrega<=d7 && activeP(p)).sort(sortByDate);

  const render7 = (elId, list, msg) => {
    document.getElementById(elId).innerHTML = list.length ? list.map(p=>pedidoCardHTML(p)).join('') : emptyHTML(msg);
  };
  render7('dash-hoje',   hoje,   'Nenhuma entrega hoje.');
  render7('dash-amanha', ama,    'Nenhuma entrega amanhã.');
  render7('dash-semana', semana, 'Nenhuma entrega nos próximos 7 dias.');

  const lh = document.getElementById('dash-late-header');
  const ll = document.getElementById('dash-late-list');
  if (atrasados.length) {
    lh.style.display='flex';
    ll.innerHTML = atrasados.map(p=>pedidoCardHTML(p)).join('');
  } else { lh.style.display='none'; ll.innerHTML=''; }

  const nb = document.getElementById('notif-badge');
  nb.style.display = atrasados.length ? 'flex' : 'none';
  nb.textContent = atrasados.length;
}
/* ── AVISOS DE ENTREGA (hoje/amanhã) ─────────────── */
function renderAvisosEntrega() {
  const pedidos = load(K.P);
  const hoje = todayStr(), amanha = offsetDate(1);
  const ativo = p => p.status !== 'Entregue' && p.status !== 'Cancelado';
  const doHoje   = pedidos.filter(p => p.dataEntrega === hoje   && ativo(p)).sort(sortByDate);
  const doAmanha = pedidos.filter(p => p.dataEntrega === amanha && ativo(p)).sort(sortByDate);
  const el = document.getElementById('dash-avisos');

  if (!doHoje.length && !doAmanha.length) { el.innerHTML = ''; return; }

  const card = (p, tipo) => {
    const wa = p.whatsapp ? `https://wa.me/55${p.whatsapp.replace(/\D/g,'')}` : null;
    const label = tipo === 'hoje' ? 'entrega hoje' : 'entrega amanhã';
    return `
    <div class="aviso-card ${tipo}">
      <div>
        <div class="aviso-titulo">${tipo === 'hoje' ? '🔴' : '🟡'} ${p.nome || '—'}</div>
        <div class="aviso-detalhe">${p.produtos ? (p.produtos.length > 46 ? p.produtos.slice(0,46)+'…' : p.produtos) + ' · ' : ''}${label}</div>
      </div>
      <div class="aviso-acoes">
        <button class="btn btn-ghost btn-sm" onclick="openDetail('${p.id}')">Ver</button>
        ${wa ? `<button class="btn btn-ghost btn-sm" onclick="window.open('${wa}','_blank')">WhatsApp</button>` : ''}
        <select class="form-control" style="width:auto;padding:7px 26px 7px 10px;font-size:12px" onchange="mudarStatusRapido('${p.id}',this.value)" onclick="event.stopPropagation()">
          <option value="Novo" ${p.status==='Novo'?'selected':''}>Novo</option>
          <option value="Em Produção" ${p.status==='Em Produção'?'selected':''}>Em Produção</option>
          <option value="Pronto" ${p.status==='Pronto'?'selected':''}>Pronto</option>
          <option value="Entregue">Concluir (Entregue)</option>
        </select>
      </div>
    </div>`;
  };

  el.innerHTML = `<div class="avisos-wrap">
    ${doHoje.map(p => card(p, 'hoje')).join('')}
    ${doAmanha.map(p => card(p, 'amanha')).join('')}
  </div>`;
}
function marcarEntregueRapido(id) {
  currentDetailId = id;
  concluirPedido();
}
function mudarStatusRapido(id, novoStatus) {
  if (!novoStatus) return;
  if (novoStatus === 'Entregue') { marcarEntregueRapido(id); return; }
  const ps = load(K.P);
  const idx = ps.findIndex(p => p.id === id);
  if (idx < 0) return;
  if (ps[idx].status !== novoStatus) ps[idx].statusDesde = new Date().toISOString();
  ps[idx].status = novoStatus;
  save(K.P, ps);
  renderDashboard();
  if (currentScreen === 'pedidos') filterPedidos();
  showToast('Status de "' + (ps[idx].nome||'pedido') + '" atualizado para ' + novoStatus + '.');
}
/* ── META DO MÊS ─────────────────────────────────── */
function renderMetaCard() {
  const el = document.getElementById('dash-meta');
  appConfig = loadO(K.C);
  const meta = parseFloat(appConfig.metaMensal) || 0;

  if (!meta) {
    el.innerHTML = `<div class="meta-card" style="justify-content:flex-start">
      <div class="meta-empty">🎯 Defina uma <a href="#" onclick="navigate('config');return false;">meta mensal</a> para acompanhar seu faturamento aqui.</div>
    </div>`;
    return;
  }

  const now = new Date();
  const mesAtual = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;
  const recebidoMesReceitas = load(K.R).filter(r => r.data && r.data.startsWith(mesAtual)).reduce((s,r) => s + (r.valor||0), 0);
  const recebidoMesVendas   = load(K.V).filter(v => v.data && v.data.startsWith(mesAtual)).reduce((s,v) => s + (v.valor||0), 0);
  const recebidoMes = recebidoMesReceitas + recebidoMesVendas;
  const pct = Math.min(Math.round(recebidoMes / meta * 100), 100);
  const falta = Math.max(meta - recebidoMes, 0);
  const raio = 40, circ = 2 * Math.PI * raio, arco = circ * (1 - pct/100);
  const cor = pct >= 100 ? 'var(--success)' : pct >= 70 ? 'var(--blue-dark)' : pct >= 40 ? 'var(--gold)' : 'var(--danger)';

  el.innerHTML = `
  <div class="meta-card">
    <div class="meta-ring-wrap">
      <svg width="96" height="96" viewBox="0 0 96 96">
        <circle cx="48" cy="48" r="${raio}" fill="none" stroke="var(--cream-dark)" stroke-width="8"/>
        <circle cx="48" cy="48" r="${raio}" fill="none" stroke="${cor}" stroke-width="8"
          stroke-dasharray="${circ}" stroke-dashoffset="${arco}" stroke-linecap="round" style="transition:.6s ease"/>
      </svg>
      <div class="meta-ring-label">
        <span class="meta-ring-pct" style="color:${cor}">${pct}%</span>
        <span class="meta-ring-sub">${pct >= 100 ? 'batida!' : 'da meta'}</span>
      </div>
    </div>
    <div class="meta-info">
      <div class="meta-row"><span>Recebido</span><b style="color:var(--success)">${fmtM(recebidoMes)}</b></div>
      <div class="meta-row"><span>Meta</span><b>${fmtM(meta)}</b></div>
      <div class="meta-row"><span>${pct >= 100 ? 'Excedente' : 'Faltam'}</span><b style="color:${pct >= 100 ? 'var(--success)' : 'var(--danger)'}">${pct >= 100 ? fmtM(recebidoMes - meta) : fmtM(falta)}</b></div>
    </div>
  </div>`;
}
function showMetaConfig() {
  appConfig = loadO(K.C);
  document.getElementById('meta-edit-valor').value = appConfig.metaMensal || '';
  openModal('modal-meta');
}
function saveMeta() {
  appConfig = loadO(K.C);
  appConfig.metaMensal = parseFloat(document.getElementById('meta-edit-valor').value) || 0;
  save(K.C, appConfig);
  closeModal('modal-meta');
  renderMetaCard();
  showToast('Meta atualizada.');
}
/* ── RESUMO FINANCEIRO DO MÊS (faturamento, lucro, a receber) ───── */
function renderFinResumoDashboard() {
  const el = document.getElementById('dash-fin-resumo');
  const { rec, gasto, pend, recReceitas, recVendas } = calcFin();
  const lucro = rec - gasto;
  el.innerHTML = `
    <div class="section-header" style="margin-top:2px">
      <span class="section-title">Resumo do mês</span>
      <button class="see-all" onclick="navigate('financeiro')">Ver financeiro</button>
    </div>
    <div class="fin-grid">
      <div class="fin-tile" onclick="navigate('financeiro')" style="cursor:pointer">
        <div class="fin-tile-label">Faturamento</div>
        <div class="fin-tile-value blue">${fmtM(rec)}</div>
        ${recVendas>0?`<div style="font-size:10px;color:var(--text-soft);margin-top:3px">${fmtM(recReceitas)} receitas + ${fmtM(recVendas)} avulsas</div>`:''}
      </div>
      <div class="fin-tile" onclick="navigate('financeiro')" style="cursor:pointer">
        <div class="fin-tile-label">Lucro estimado</div>
        <div class="fin-tile-value ${lucro>=0?'green':'red'}">${fmtM(lucro)}</div>
      </div>
      <div class="fin-tile" onclick="goToScreen('financeiro')" style="cursor:pointer">
        <div class="fin-tile-label">A receber</div>
        <div class="fin-tile-value gold">${fmtM(pend)}</div>
      </div>
      <div class="fin-tile" onclick="navigate('financeiro')" style="cursor:pointer">
        <div class="fin-tile-label">Gasto do mês</div>
        <div class="fin-tile-value red">${fmtM(gasto)}</div>
      </div>
    </div>`;
}
/* ── ESTOQUE BAIXO NO DASHBOARD ───────────────────── */
function renderEstoqueBaixoDashboard() {
  const el = document.getElementById('dash-estoque-baixo');
  const mats = load(K.M).filter(m => (m.estoqueMin||0) > 0 && (m.estoque||0) <= (m.estoqueMin||0));
  if (!mats.length) { el.innerHTML = ''; return; }
  el.innerHTML = `
    <div class="section-header" style="margin-top:6px">
      <span class="section-title" style="color:var(--danger)">📦 Estoque baixo</span>
      <button class="see-all" onclick="navigate('estoque')">Ver materiais</button>
    </div>
    <div class="card" style="padding:4px 20px">
      ${mats.map(m => `
        <div class="tx-row">
          <div class="tx-left"><div class="tx-desc">${m.nome}</div></div>
          <div style="display:flex;align-items:center;gap:10px">
            <div style="text-align:right">
              <div style="font-size:13px;color:var(--danger);font-weight:600">${m.estoque||0} ${m.unidade||''}</div>
              <div style="font-size:11px;color:var(--text-soft)">mín. ${m.estoqueMin} ${m.unidade||''}</div>
            </div>
            <button class="btn btn-ghost btn-sm" onclick="openEstoqueEntradaModal('${m.id}')">+ Entrada</button>
          </div>
        </div>`).join('')}
    </div>`;
}
function renderAlertasDashboard() {
  const el = document.getElementById('dash-alertas');
  const alertas = calcularAlertasPedidos();
  if (!alertas.length) { el.innerHTML = ''; return; }
  el.innerHTML = `
    <div class="section-header" style="margin-top:6px">
      <span class="section-title">⚠️ Alertas</span>
    </div>
    <div class="card" style="padding:4px 20px">
      ${alertas.map(a => `
        <div class="tx-row" style="align-items:flex-start">
          <div style="flex:1;padding-right:10px">
            <div style="font-size:13px;color:var(--text);line-height:1.5">${a.texto}</div>
          </div>
          <div style="display:flex;gap:6px;flex-shrink:0;flex-wrap:wrap;justify-content:flex-end">
            <button class="btn btn-ghost btn-sm" onclick="openDetail('${a.id}')">Ver</button>
            <button class="btn btn-ghost btn-sm" onclick="snoozeAlertaPedido('${a.id}','${a.tipo}')">Adiar 7d</button>
          </div>
        </div>
      `).join('')}
    </div>`;
}
function snoozeAlertaPedido(id, tipo) {
  const ps = load(K.P);
  const idx = ps.findIndex(p => p.id === id);
  if (idx < 0) return;
  ps[idx].alertaSnoozeAte = offsetDate(7);
  ps[idx].alertaSnoozeTipo = tipo;
  save(K.P, ps);
  renderAlertasDashboard();
  showToast('Alerta adiado por 7 dias.');
}
/* ── PEDIDOS ─────────────────────────────────────── */
function renderPedidos(filter) {
  if (filter && filter!=='Todos') {
    document.querySelectorAll('#chips-pedidos .chip').forEach(c=>c.classList.toggle('active',c.dataset.status===filter));
  }
  filterPedidos();
}
function filterPedidos() {
  const pedidos = load(K.P);
  const q = (document.getElementById('search-pedidos')?.value||'').toLowerCase();
  const chip = document.querySelector('#chips-pedidos .chip.active')?.dataset.status||'Todos';
  const list = pedidos.filter(p=>{
    const ms = chip==='Todos'||p.status===chip;
    const mq = !q||[p.nome,p.tema,p.produtos,p.ocasiao].some(v=>v?.toLowerCase().includes(q));
    return ms&&mq;
  }).sort(sortByDate);
  const el = document.getElementById('list-pedidos');
  if (!list.length) { el.innerHTML = emptyHTML('Nenhum pedido encontrado.<br><strong>Toque no + para adicionar.</strong>'); return; }

  const porMes = agruparPedidosPorMes(list);
  const meses = Object.keys(porMes).sort((a,b)=> a==='sem-data' ? 1 : b==='sem-data' ? -1 : a.localeCompare(b));
  // Na primeira vez que um mês aparece, ele começa expandido (mantém os cards visíveis como antes)
  meses.forEach(ym=>{ if (!pedidosMesesInicializado.has(ym)) { pedidosMesesExpandido.add(ym); pedidosMesesInicializado.add(ym); } });
  el.innerHTML = meses.map(ym=>renderPilhaMesPedidos(ym, porMes[ym])).join('');
}
function togglePedidoMes(ym){
  if (pedidosMesesExpandido.has(ym)) pedidosMesesExpandido.delete(ym);
  else pedidosMesesExpandido.add(ym);
  filterPedidos();
}
function renderPilhaMesPedidos(ym, itens){
  const isOpen = pedidosMesesExpandido.has(ym);
  const label = ym === 'sem-data' ? 'Sem data de entrega' : mesLabel(ym);
  const totalValor = itens.reduce((s,p)=>s+(p.total||0),0);
  return `
    <div class="card" style="padding:0;margin-bottom:12px;overflow:hidden">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;cursor:pointer" onclick="togglePedidoMes('${ym}')">
        <div style="display:flex;align-items:center;gap:10px;flex-wrap:wrap">
          <span style="font-family:var(--font-display);font-size:17px;font-weight:600">${isOpen?'▾':'▸'} ${label}</span>
          <span style="font-size:12px;color:var(--text-soft)">${itens.length} pedido${itens.length===1?'':'s'}${totalValor>0?' · '+fmtM(totalValor):''}</span>
        </div>
        <span style="font-size:12px;color:var(--text-soft);flex-shrink:0">${isOpen?'recolher':'expandir'}</span>
      </div>
      ${isOpen?`<div style="border-top:1px solid var(--border-light);padding:12px 14px 4px">
        ${itens.map(p=>pedidoCardHTML(p)).join('')}
      </div>`:''}
    </div>`;
}
function setChip(el, gid) {
  document.querySelectorAll('#'+gid+' .chip').forEach(c=>c.classList.remove('active'));
  el.classList.add('active');
  if (currentScreen==='pedidos') filterPedidos();
}

// Resumo curto dos produtos de um pedido: usa os itens do catálogo (com qtd) quando existirem,
// senão cai para o texto livre digitado em "Produtos vendidos"
function produtosResumoPedido(p) {
  if (p.itens && p.itens.length) {
    return p.itens.map(i => `${i.qtd}x ${i.produtoNome}`).join(', ');
  }
  return p.produtos || '';
}
function pedidoCardHTML(p) {
  const atras = isAtrasado(p);
  const dias  = atras ? diasAtraso(p) : 0;
  const pend  = (p.total||0)-(p.pago||0);
  const sClass= { 'Novo':'s-novo','Em Produção':'s-producao','Pronto':'s-pronto','Entregue':'s-entregue','Cancelado':'s-cancelado' }[p.status]||'';
  const bClass= { 'Novo':'badge-novo','Em Produção':'badge-emproducao','Pronto':'badge-pronto','Entregue':'badge-entregue','Cancelado':'badge-cancelado' }[p.status]||'';
  const wa = p.whatsapp ? `https://wa.me/55${p.whatsapp.replace(/\D/g,'')}` : null;
  const qtdTotalItens = (p.itens||[]).reduce((s,i)=>s+(i.qtd||0),0);
  const produtosResumo = produtosResumoPedido(p);
  return `
  <div class="pedido-card ${atras?'s-atrasado':sClass}" onclick="openDetail('${p.id}')">
    <div class="pedido-card-header">
      <div>
        <div class="pedido-nome">${p.nome||'—'}</div>
        <div class="pedido-sub">${[p.tema,p.ocasiao].filter(Boolean).join(' · ')||'—'}</div>
      </div>
      <div style="display:flex;flex-direction:column;align-items:flex-end;gap:5px">
        <span class="badge ${bClass}">${p.status}</span>
        ${atras?`<span class="tag-atrasado">${dias}d atraso</span>`:''}
      </div>
    </div>
    <div class="pedido-meta">
      <span class="pedido-meta-item">
        <svg viewBox="0 0 24 24"><rect x="3" y="4" width="18" height="18" rx="2"/><line x1="16" y1="2" x2="16" y2="6"/><line x1="8" y1="2" x2="8" y2="6"/><line x1="3" y1="10" x2="21" y2="10"/></svg>
        ${p.dataEntrega?formatDate(p.dataEntrega):'—'}
      </span>
      ${produtosResumo?`<span class="pedido-meta-item" title="${produtosResumo.replace(/"/g,'&quot;')}"><svg viewBox="0 0 24 24"><path d="M21 16V8a2 2 0 0 0-1-1.73l-7-4a2 2 0 0 0-2 0l-7 4A2 2 0 0 0 3 8v8a2 2 0 0 0 1 1.73l7 4a2 2 0 0 0 2 0l7-4A2 2 0 0 0 21 16z"/></svg>${produtosResumo.length>32?produtosResumo.slice(0,32)+'…':produtosResumo}${qtdTotalItens>0?` <b style="color:var(--text-mid)">(${qtdTotalItens} un.)</b>`:''}</span>`:''}
      <div style="margin-left:auto;display:flex;align-items:center;gap:8px;flex-wrap:wrap">
        ${p.total>0?`<span class="pedido-meta-item" style="font-weight:700;color:var(--blue-dark)">${fmtM(p.total)}</span>`:''}
        ${pend>0?`<span class="tag-pendente" style="margin-left:0">${fmtM(pend)} pendente</span>`:''}
        ${wa?`<button class="btn-icon-wa" onclick="event.stopPropagation();window.open('${wa}','_blank')" title="WhatsApp">
          <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/></svg>
        </button>`:''}
      </div>
    </div>
  </div>`;
}

// Calcula o breakdown financeiro completo de um pedido: materiais, outros custos, lucro bruto e margem
function renderCustoRealPedido(p){
  const temItens  = p.itens && p.itens.length;
  const temExtras = (p.custosExtras||0) > 0;
  if (!temItens && !temExtras) return '';
  const { detalhes, custoMateriais, custoExtras, lucroBruto, margem } = calcLucroPedido(p);
  return `
    <div class="card" style="background:var(--blue-pale);border:none;box-shadow:none;padding:14px 16px;margin-top:14px">
      <div class="card-label" style="margin-bottom:8px">Financeiro do pedido</div>
      <div class="meta-row"><span>Valor pago pelo cliente</span><b style="color:var(--success)">${fmtM(p.pago)}</b></div>
      <div class="meta-row"><span>Custo dos materiais</span><b style="color:var(--danger)">${fmtM(custoMateriais)}</b></div>
      <div class="meta-row"><span>Outros custos${p.custosExtrasDesc?' ('+p.custosExtrasDesc+')':''}</span><b style="color:var(--danger)">${fmtM(custoExtras)}</b></div>
      <div class="meta-row"><span>Preço de venda (total)</span><b>${fmtM(p.total)}</b></div>
      <div class="meta-row"><span>Lucro bruto real</span><b style="color:${lucroBruto>=0?'var(--success)':'var(--danger)'}">${fmtM(lucroBruto)}</b></div>
      <div class="meta-row"><span>Margem de lucro</span><b style="color:${margem>=0?'var(--success)':'var(--danger)'}">${margem.toFixed(1)}%</b></div>
      ${detalhes.length?`<div style="font-size:11px;color:var(--text-soft);margin-top:8px">Insumos: ${detalhes.map(d=>`${d.nome} (${d.qtd} ${d.unidade})`).join(', ')}</div>`:''}
      ${renderDesperdicioDetalhe(p)}
    </div>`;
}

// Mostra o material perdido/desperdiçado registrado ao concluir o pedido, se houver
function renderDesperdicioDetalhe(p){
  if (!p.materialDesperdicado || !p.materialDesperdicado.length) return '';
  const mats = load(K.M);
  const linhas = p.materialDesperdicado.map(d=>{
    const m = mats.find(x=>x.id===d.matId);
    return `${m?m.nome:'Material removido'} (${d.qtd} ${m?.unidade||''})`;
  }).join(', ');
  return `<div style="font-size:11px;color:var(--danger);margin-top:8px">🗑️ Desperdício registrado: ${linhas}</div>`;
}

// Tabela detalhada dos itens do pedido: quantidade, valor unitário e subtotal de cada produto
function renderItensDetalhePedido(p) {
  if (!p.itens || !p.itens.length) return '';
  const totalItens = p.itens.reduce((s,i)=>s+(i.precoUnit||0)*(i.qtd||0),0);
  const qtdTotal    = p.itens.reduce((s,i)=>s+(i.qtd||0),0);
  const divergente  = (p.total||0) > 0 && Math.abs((p.total||0) - totalItens) > 0.01;
  return `
    <div class="card" style="margin-top:14px">
      <div class="card-label">Itens do pedido</div>
      <div style="display:flex;font-size:10px;font-weight:700;letter-spacing:.6px;text-transform:uppercase;color:var(--text-soft);padding-bottom:8px;border-bottom:1px solid var(--border-light)">
        <span style="flex:1">Produto</span>
        <span style="width:44px;text-align:center">Qtd</span>
        <span style="width:74px;text-align:right">Unitário</span>
        <span style="width:74px;text-align:right">Subtotal</span>
      </div>
      ${p.itens.map(i=>`
        <div style="display:flex;align-items:center;font-size:13px;padding:9px 0;border-bottom:1px solid var(--border-light)">
          <span style="flex:1;color:var(--text)">${i.produtoNome}</span>
          <span style="width:44px;text-align:center;color:var(--text-mid)">${i.qtd}</span>
          <span style="width:74px;text-align:right;color:var(--text-mid)">${fmtM(i.precoUnit)}</span>
          <span style="width:74px;text-align:right;font-weight:600;color:var(--text)">${fmtM((i.precoUnit||0)*(i.qtd||0))}</span>
        </div>`).join('')}
      <div style="display:flex;align-items:center;padding-top:10px">
        <span style="flex:1;font-size:12px;color:var(--text-soft)">${qtdTotal} item${qtdTotal===1?'':'ns'} no total</span>
        <span style="font-size:15px;font-weight:700;color:var(--blue-dark)">${fmtM(totalItens)}</span>
      </div>
      ${divergente?`<div style="margin-top:10px;padding:8px 10px;background:var(--rose-pale);border:1px solid var(--rose-light);border-radius:8px;font-size:11px;color:var(--rose-dark)">⚠️ O valor total do pedido (${fmtM(p.total)}) é diferente da soma dos itens (${fmtM(totalItens)}).</div>`:''}
    </div>`;
}
function openDetail(id) {
  const p = load(K.P).find(p=>p.id===id);
  if (!p) return;
  currentDetailId = id;
  const atras = isAtrasado(p);
  const dias  = atras ? diasAtraso(p) : 0;
  const pend  = (p.total||0)-(p.pago||0);
  const pct   = p.total>0?Math.round((p.pago/p.total)*100):0;
  const bClass= { 'Novo':'badge-novo','Em Produção':'badge-emproducao','Pronto':'badge-pronto','Entregue':'badge-entregue','Cancelado':'badge-cancelado' }[p.status]||'';

  document.getElementById('det-nome').textContent = p.nome;
  document.getElementById('det-sub').textContent  = [p.tema,p.ocasiao].filter(Boolean).join(' · ')||'—';
  document.getElementById('det-badge').innerHTML  = `<span class="badge ${bClass}">${p.status}</span>`;
  document.getElementById('det-body').innerHTML = `
    ${p.whatsapp?`<div class="detail-row"><span class="detail-key">WhatsApp</span><span class="detail-val"><a href="https://wa.me/55${p.whatsapp.replace(/\D/g,'')}" style="color:var(--success);font-weight:600">${p.whatsapp}</a></span></div>`:''}
    <div class="detail-row"><span class="detail-key">Data de entrega</span><span class="detail-val" style="${atras?'color:var(--danger);font-weight:700':''}">
      ${p.dataEntrega?formatDate(p.dataEntrega):'—'}${atras?` · ${dias}d atrasado`:''}
    </span></div>
    ${p.dataEvento?`<div class="detail-row"><span class="detail-key">Data do evento</span><span class="detail-val">${formatDate(p.dataEvento)}</span></div>`:''}
    <div class="detail-row"><span class="detail-key">Produtos</span><span class="detail-val">${p.produtos||'—'}</span></div>
    ${renderItensDetalhePedido(p)}
    <div class="detail-row"><span class="detail-key">Valor total</span><span class="detail-val">${fmtM(p.total)}</span></div>
    <div class="detail-row"><span class="detail-key">Valor pago</span><span class="detail-val" style="color:var(--success)">${fmtM(p.pago)}</span></div>
    <div class="detail-row"><span class="detail-key">Pendente</span><span class="detail-val" style="color:${pend>0?'var(--danger)':'var(--success)'}">${fmtM(pend)}</span></div>
    <div style="margin:14px 0 4px">
      <div class="progress-track"><div class="progress-fill" style="width:${pct}%"></div></div>
      <div class="progress-legend"><span>0%</span><span style="color:var(--blue-dark);font-weight:600">${pct}% pago</span><span>100%</span></div>
    </div>
    ${p.obs?`<div class="detail-row"><span class="detail-key">Observações</span><span class="detail-val">${p.obs}</span></div>`:''}
    ${renderCustoRealPedido(p)}
  `;
  // Mostrar botão concluir só se não for Entregue ou Cancelado
  const wrap = document.getElementById('det-concluir-wrap');
  wrap.style.display = (p.status !== 'Entregue' && p.status !== 'Cancelado') ? 'block' : 'none';

  openModal('modal-detalhe');
}
function editFromDetail() {
  closeModal('modal-detalhe');
  const p = load(K.P).find(p=>p.id===currentDetailId);
  if (p) openPedidoModal(p);
}
function concluirPedido() {
  const p = load(K.P).find(p => p.id === currentDetailId);
  if (!p) return;
  // Pré-preencher modal de receita
  const pendente = Math.max(0, (p.total||0) - (p.pago||0));
  const valorSugerido = pendente > 0 ? pendente : (p.total || 0);
  document.getElementById('concluir-valor').value = valorSugerido.toFixed(2);
  document.getElementById('concluir-valor-preview').textContent = fmtM(valorSugerido);
  document.getElementById('concluir-cliente-preview').textContent = p.nome + (p.produtos ? ' · ' + p.produtos.slice(0,40) : '');
  document.getElementById('concluir-data').value = todayStr();
  desperdicioAtual = [];
  populateMaterialSelectDesperdicio();
  renderDesperdicioList();
  closeModal('modal-detalhe');
  openModal('modal-concluir');
}
function populateMaterialSelectDesperdicio(){
  const mats = load(K.M);
  const sel = document.getElementById('concluir-desp-mat');
  sel.innerHTML = mats.length
    ? mats.map(m=>`<option value="${m.id}">${m.nome} (${fmtM(m.custo)}/${m.unidade||'un'})</option>`).join('')
    : '<option value="">Nenhum material cadastrado</option>';
}
function addDesperdicioItem(){
  const matId = document.getElementById('concluir-desp-mat').value;
  const qtd   = parseFloat(document.getElementById('concluir-desp-qtd').value);
  if (!matId){ showToast('Cadastre um material primeiro'); return; }
  if (!qtd || qtd<=0){ showToast('Informe a quantidade perdida'); return; }
  const idx = desperdicioAtual.findIndex(d=>d.matId===matId);
  if (idx>=0) desperdicioAtual[idx].qtd += qtd; else desperdicioAtual.push({ matId, qtd });
  document.getElementById('concluir-desp-qtd').value = '';
  renderDesperdicioList();
}
function removeDesperdicioItem(i){ desperdicioAtual.splice(i,1); renderDesperdicioList(); }
function renderDesperdicioList(){
  const mats = load(K.M);
  const el = document.getElementById('concluir-desperdicio-list');
  el.innerHTML = desperdicioAtual.length ? desperdicioAtual.map((d,i)=>{
    const m = mats.find(x=>x.id===d.matId);
    return `<div class="tx-row" style="padding:8px 0">
      <div class="tx-left"><div style="font-size:13px">${m?m.nome:'Material removido'} — ${d.qtd} ${m?.unidade||''}</div></div>
      <div style="display:flex;align-items:center;gap:8px">
        <span style="font-size:12px;color:var(--danger)">${fmtM(m?m.custo*d.qtd:0)}</span>
        <button class="btn btn-ghost btn-sm" onclick="removeDesperdicioItem(${i})">Remover</button>
      </div>
    </div>`;
  }).join('') : '<div style="font-size:12px;color:var(--text-soft)">Nenhum desperdício adicionado.</div>';
}
function _finalizarPedido(valorRecebidoAgora) {
  const ps = load(K.P);
  const idx = ps.findIndex(p => p.id === currentDetailId);
  if (idx >= 0) {
    // Aplica material desperdiçado: retira do estoque e soma ao custo do pedido
    if (desperdicioAtual.length) {
      const mats = load(K.M);
      let custoDesperdicio = 0;
      desperdicioAtual.forEach(d => {
        const mi = mats.findIndex(m => m.id === d.matId);
        if (mi >= 0) {
          mats[mi].estoque = (mats[mi].estoque || 0) - d.qtd;
          custoDesperdicio += (mats[mi].custo || 0) * d.qtd;
          logMovimentoEstoque(d.matId, 'saida', d.qtd, mats[mi].custo, 'Desperdício em pedido');
        }
      });
      save(K.M, mats);
      ps[idx].custosExtras = (ps[idx].custosExtras || 0) + custoDesperdicio;
      ps[idx].materialDesperdicado = (ps[idx].materialDesperdicado || []).concat(desperdicioAtual);
      const descAtual = ps[idx].custosExtrasDesc || '';
      ps[idx].custosExtrasDesc = descAtual ? descAtual + ' + desperdício' : 'Desperdício de materiais';
    }
    const total = ps[idx].total || 0;
    // Só soma ao valor pago o que foi de fato lançado agora (não força quitação total)
    if (valorRecebidoAgora) {
      const novoPago = (ps[idx].pago || 0) + valorRecebidoAgora;
      ps[idx].pago = total > 0 ? Math.min(total, novoPago) : novoPago;
    }
    ps[idx].status = 'Entregue';
    ps[idx].pendente = Math.max(0, total - (ps[idx].pago || 0));
    save(K.P, ps);
  }
  currentDetailId = null;
  desperdicioAtual = [];
  closeModal('modal-concluir');
  if (currentScreen === 'pedidos') filterPedidos();
  else renderDashboard();
}
function concluirSemReceita() {
  _finalizarPedido(0);
  showToast('Pedido marcado como Entregue.');
}
function concluirComReceita() {
  const valor = parseFloat(document.getElementById('concluir-valor').value);
  const data  = document.getElementById('concluir-data').value;
  if (!valor || !data) { showToast('Preencha o valor e a data'); return; }
  const p = load(K.P).find(p => p.id === currentDetailId);
  const rs = load(K.R);
  rs.push({
    id: 'r' + Date.now(),
    data,
    cliente: p?.nome || '',
    valor,
    ref: 'Pedido concluído' + (p?.produtos ? ' · ' + p.produtos.slice(0,40) : '')
  });
  save(K.R, rs);
  _finalizarPedido(valor);
  showToast('Pedido concluído e receita lançada!');
}
function deletePedidoFromDetail() {
  if (!currentDetailId) { showToast('Erro: pedido não identificado.'); return; }
  if (!confirm('Excluir este pedido?')) return;
  const pedidoExcluido = load(K.P).find(p => p.id === currentDetailId);
  fbDel('pedidos', currentDetailId);
  const ps = load(K.P).filter(p => p.id !== currentDetailId);
  save(K.P, ps);
  aplicarConsumoEstoque(pedidoExcluido?.itens, []);
  currentDetailId = null;
  closeModal('modal-detalhe');
  if (currentScreen === 'pedidos') filterPedidos();
  else renderDashboard();
  showToast('Pedido excluído.');
}
/* ── MENSAGEM DE CONFIRMAÇÃO E RECIBO ────────────── */
let _msgWaLink = null;
function abrirModalMsg(titulo, texto, waLink) {
  document.getElementById('modal-msg-title').textContent = titulo;
  document.getElementById('msg-texto').value = texto;
  _msgWaLink = waLink;
  document.getElementById('msg-wa-btn').style.display = waLink ? 'inline-flex' : 'none';
  openModal('modal-msg');
}
function copiarMsgTexto() {
  const texto = document.getElementById('msg-texto').value;
  navigator.clipboard.writeText(texto).then(()=>showToast('Copiado!')).catch(()=>showToast('Não foi possível copiar.'));
}
function abrirWhatsappMsg() {
  if (!_msgWaLink) { showToast('Este cliente não tem WhatsApp cadastrado.'); return; }
  const texto = document.getElementById('msg-texto').value;
  window.open(`${_msgWaLink}?text=${encodeURIComponent(texto)}`, '_blank');
}
function gerarMsgConfirmacaoPedido(p) {
  const pend = Math.max(0, (p.total||0) - (p.pago||0));
  const linhas = [
    '🧁 Pedido confirmado — Graça em Papel',
    `Cliente: ${p.nome || '—'}`,
    p.produtos ? `Produtos: ${p.produtos}` : null,
    p.dataEvento ? `Data do evento: ${formatDate(p.dataEvento)}` : null,
    `📅 Entrega: ${p.dataEntrega ? formatDate(p.dataEntrega) : '—'}`,
    p.total ? `💰 Valor total: ${fmtM(p.total)}` : null,
    p.pago > 0 ? `✅ Sinal recebido: ${fmtM(p.pago)}` : null,
    p.total ? (pend > 0 ? `💵 Restante: ${fmtM(pend)} a combinar` : '✅ Pagamento quitado.') : null,
    '',
    'Obrigada pela confiança! Vou capricho no seu pedido. 🎀'
  ].filter(l => l !== null);
  return linhas.join('\n');
}
function abrirMsgConfirmacao(id) {
  const p = load(K.P).find(x => x.id === id);
  if (!p) { showToast('Pedido não encontrado.'); return; }
  const wa = p.whatsapp ? `https://wa.me/55${p.whatsapp.replace(/\D/g,'')}` : null;
  abrirModalMsg('📋 Mensagem de confirmação', gerarMsgConfirmacaoPedido(p), wa);
}
function gerarReciboPedido(p) {
  const pend = Math.max(0, (p.total||0) - (p.pago||0));
  const numero = `${(p.dataEntrega || todayStr()).slice(0,4)}-${(p.id||'').replace(/\D/g,'').slice(-4) || '0000'}`;
  const linhas = [
    'Graça em Papel — Comprovante',
    `Recibo nº ${numero}`,
    '',
    `Cliente: ${p.nome || '—'}`,
    p.produtos ? `Produtos: ${p.produtos}` : null,
    `Valor total: ${fmtM(p.total)}`,
    `Valor pago: ${fmtM(p.pago)}`,
    pend > 0 ? `Saldo pendente: ${fmtM(pend)}` : 'Situação: Quitado ✅',
    p.dataEntrega ? `Entrega: ${formatDate(p.dataEntrega)}` : null,
    '',
    'Obrigada pela confiança em nosso trabalho!',
    'Graça em Papel'
  ].filter(l => l !== null);
  return linhas.join('\n');
}
function abrirRecibo(id) {
  const p = load(K.P).find(x => x.id === id);
  if (!p) { showToast('Pedido não encontrado.'); return; }
  const wa = p.whatsapp ? `https://wa.me/55${p.whatsapp.replace(/\D/g,'')}` : null;
  abrirModalMsg('🧾 Recibo', gerarReciboPedido(p), wa);
}
/* -- Cadastro de cliente (CRUD de verdade) -- */
function openClienteFormModal(c = null) {
  document.getElementById('modal-cliente-form-title').textContent = c ? 'Editar cliente' : 'Novo cliente';
  document.getElementById('cf-id').value        = c?.id || '';
  document.getElementById('cf-nome').value      = c?.nome || '';
  document.getElementById('cf-whatsapp').value  = c?.whatsapp || '';
  document.getElementById('cf-obs').value       = c?.obs || '';
  document.getElementById('cf-delete-btn').style.display = c ? 'inline-flex' : 'none';
  openModal('modal-cliente-form');
}
function saveClienteForm() {
  const nome = document.getElementById('cf-nome').value.trim();
  if (!nome) { showToast('Informe o nome do cliente'); return; }
  const id = document.getElementById('cf-id').value || 'cli' + Date.now();
  const cs = load(K.CLI);
  const idx = cs.findIndex(x => x.id === id);
  const obj = {
    id, nome,
    whatsapp: document.getElementById('cf-whatsapp').value.trim(),
    obs:      document.getElementById('cf-obs').value.trim(),
    criado:   idx >= 0 ? (cs[idx].criado || new Date().toISOString()) : new Date().toISOString()
  };
  if (idx >= 0) cs[idx] = obj; else cs.push(obj);
  save(K.CLI, cs);
  closeModal('modal-cliente-form');
  if (currentScreen === 'clientes') renderClientes();
  showToast('Cliente salvo.');
}
function deleteClienteForm() {
  const id = document.getElementById('cf-id').value;
  if (!id) return;
  if (!confirm('Excluir este cliente? Os pedidos vinculados mantêm o nome/WhatsApp salvos, mas perdem o vínculo com o cadastro.')) return;
  fbDel('clientes', id);
  save(K.CLI, load(K.CLI).filter(c => c.id !== id));
  const ps = load(K.P);
  let mudou = false;
  ps.forEach(p => { if (p.clienteId === id) { p.clienteId = ''; mudou = true; } });
  if (mudou) save(K.P, ps);
  closeModal('modal-cliente-form');
  closeModal('modal-cliente');
  if (currentScreen === 'clientes') renderClientes();
  showToast('Cliente excluído.');
}

// Transforma um cliente "legado" (agrupado por nome/whatsapp) em um cadastro de verdade,
// vinculando retroativamente todos os pedidos correspondentes
/* -- Seletor de cliente dentro do pedido (com atalho de cadastro rápido) -- */
function populateClienteSelectPedido(selectedId) {
  const cs = load(K.CLI);
  const sel = document.getElementById('p-cliente-select');
  sel.innerHTML = '<option value="">— Sem vincular (digitar manualmente) —</option>'
    + cs.map(c => `<option value="${c.id}">${c.nome}${c.whatsapp ? ' · ' + c.whatsapp : ''}</option>`).join('')
    + '<option value="__new__">➕ Cadastrar novo cliente...</option>';
  sel.value = selectedId || '';
}
function onClienteSelectChange(sel) {
  if (sel.value === '__new__') {
    const prev = document.getElementById('p-cliente-id').value || '';
    sel.value = prev; // mantém o valor anterior visualmente até o cadastro rápido resolver
    openClienteQuickModal();
    return;
  }
  document.getElementById('p-cliente-id').value = sel.value;
  if (sel.value) {
    const c = load(K.CLI).find(x => x.id === sel.value);
    if (c) {
      document.getElementById('p-nome').value     = c.nome || '';
      document.getElementById('p-whatsapp').value = c.whatsapp || '';
    }
  }
}
function openClienteQuickModal() {
  document.getElementById('cq-nome').value = '';
  document.getElementById('cq-whatsapp').value = '';
  openModal('modal-cliente-quick');
  setTimeout(() => document.getElementById('cq-nome')?.focus(), 250);
}
function saveClienteQuick() {
  const nome = document.getElementById('cq-nome').value.trim();
  if (!nome) { showToast('Informe o nome do cliente'); return; }
  const id = 'cli' + Date.now();
  const obj = { id, nome, whatsapp: document.getElementById('cq-whatsapp').value.trim(), obs: '', criado: new Date().toISOString() };
  const cs = load(K.CLI); cs.push(obj); save(K.CLI, cs);
  closeModal('modal-cliente-quick');
  populateClienteSelectPedido(id);
  document.getElementById('p-cliente-id').value = id;
  document.getElementById('p-nome').value = obj.nome;
  document.getElementById('p-whatsapp').value = obj.whatsapp;
  showToast('Cliente cadastrado! Já selecionado.');
}

// Regras simples de fidelização — ajustável conforme o negócio crescer
function renderClientes() {
  const q = (document.getElementById('search-clientes')?.value || '').toLowerCase();
  const clientes = aggregateClientes().filter(c => !q || (c.nome || '').toLowerCase().includes(q));
  document.getElementById('list-clientes').innerHTML = clientes.length
    ? clientes.map(clienteCardHTML).join('')
    : emptyHTML('Nenhum cliente encontrado.<br><strong>Clientes aparecem aqui após o primeiro pedido.</strong>');
}
function clienteCardHTML(c) {
  const fid = fidelidadeInfo(c);
  const wa  = c.whatsapp ? `https://wa.me/55${c.whatsapp.replace(/\D/g, '')}` : null;
  return `
  <div class="pedido-card" onclick="openClienteDetail('${c.key}')">
    <div class="pedido-card-header">
      <div>
        <div class="pedido-nome">${c.nome || '—'}</div>
        <div class="pedido-sub">${c.qtdPedidos} pedido${c.qtdPedidos === 1 ? '' : 's'} · última compra ${c.ultimaCompra ? formatDate(c.ultimaCompra) : '—'}</div>
      </div>
      <div style="display:flex;flex-direction:column;align-items:flex-end;gap:5px">
        ${fid ? `<span class="badge badge-pronto">${fid.label}</span>` : ''}
        ${!c.cadastrado ? `<span class="badge badge-emproducao">Não cadastrado</span>` : ''}
      </div>
    </div>
    <div class="pedido-meta">
      <span class="pedido-meta-item">Total gasto: ${fmtM(c.totalGasto)}</span>
      <div style="margin-left:auto">
        ${wa ? `<button class="btn-icon-wa" onclick="event.stopPropagation();window.open('${wa}','_blank')" title="WhatsApp">
          <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/></svg>
        </button>` : ''}
      </div>
    </div>
  </div>`;
}
function openClienteDetail(key) {
  const c = aggregateClientes().find(x => x.key === key);
  if (!c) return;
  currentClienteKey = key;
  const fid = fidelidadeInfo(c);
  const ordenados = [...c.pedidos].sort((a, b) => (b.dataEntrega || '').localeCompare(a.dataEntrega || ''));
  const atual = ordenados.find(p => ['Novo', 'Em Produção', 'Pronto'].includes(p.status)) || ordenados[0];
  const historico = atual ? ordenados.filter(p => p.id !== atual.id) : ordenados;

  document.getElementById('cli-nome').textContent = c.nome || '—';
  document.getElementById('cli-sub').textContent   = c.whatsapp ? ('WhatsApp: ' + c.whatsapp) : 'Sem WhatsApp cadastrado';
  document.getElementById('cli-badge').innerHTML   = fid ? `<span class="badge badge-pronto">${fid.label}</span>` : '';

  document.getElementById('cli-cadastro-acoes').innerHTML = c.cadastrado
    ? `<button class="btn btn-ghost btn-sm" onclick="openClienteFormModal(${JSON.stringify({id:c.clienteId,nome:c.nome,whatsapp:c.whatsapp,obs:c.obs}).replace(/"/g,'&quot;')})">✎ Editar cadastro</button>${c.obs?`<div style="font-size:12px;color:var(--text-mid);margin-top:8px;line-height:1.6">${c.obs}</div>`:''}`
    : `<div class="card" style="background:var(--rose-pale);border-color:var(--rose-light);padding:12px 14px;margin:0">
        <div style="font-size:12px;color:var(--text-mid);line-height:1.6;margin-bottom:10px">Este cliente ainda não tem cadastro próprio — os dados vêm dos pedidos. Cadastre para editar nome/WhatsApp diretamente e manter tudo vinculado.</div>
        <button class="btn btn-rose btn-sm" style="width:100%" onclick="migrarClienteLegado('${c.key}')">Cadastrar este cliente</button>
      </div>`;

  document.getElementById('cli-stats').innerHTML = `
    <div class="fin-grid">
      <div class="fin-tile"><div class="fin-tile-label">Total gasto</div><div class="fin-tile-value green">${fmtM(c.totalGasto)}</div></div>
      <div class="fin-tile"><div class="fin-tile-label">Pedidos</div><div class="fin-tile-value blue">${c.qtdPedidos}</div></div>
      <div class="fin-tile"><div class="fin-tile-label">Última compra</div><div class="fin-tile-value gold" style="font-size:15px">${c.ultimaCompra ? formatDate(c.ultimaCompra) : '—'}</div></div>
      <div class="fin-tile"><div class="fin-tile-label">Cliente desde</div><div class="fin-tile-value" style="font-size:13px">${tempoDesde(c.primeiraCompra)}</div></div>
    </div>`;

  const _iaPerfilExistente = loadIaPerfis()[c.key];
  document.getElementById('cli-ia-btn-wrap').innerHTML = `
    <button class="btn btn-ghost btn-sm" style="width:100%" onclick="abrirAnaliseIA('${c.key}')">
      🧠 ${_iaPerfilExistente ? 'Atualizar análise / importar nova conversa' : 'Gerar perfil e sugestões com IA'}
    </button>`;
  // Mostra o perfil (se já existir) direto aqui na tela do cliente, sem precisar abrir a Área IA
  _iaClienteAtual = c.key;
  renderIaResultado(_iaPerfilExistente || null, 'cli-ia-perfil');

  document.getElementById('cli-atual').innerHTML = atual ? `
    <div class="card-label">Pedido em destaque</div>
    ${pedidoCardHTML(atual)}
  ` : '';

  document.getElementById('cli-historico').innerHTML = `
    <div class="card-label" style="margin-top:16px">Histórico de compras</div>
    ${historico.length ? historico.map(p => pedidoCardHTML(p)).join('') : emptyHTML('Nenhuma outra compra registrada ainda.')}
  `;

  const fidWrap = document.getElementById('cli-fideliza');
  if (fid) {
    fidWrap.style.display = 'block';
    fidWrap.querySelector('.fideliza-texto').textContent =
      `${c.nome || 'Este cliente'} já é ${fid.label.replace(/[✨💛]/g,'').trim()}, com ${c.qtdPedidos} pedido${c.qtdPedidos===1?'':'s'} e ${fmtM(c.totalGasto)} em compras. Que tal um mimo de agradecimento?`;
  } else {
    fidWrap.style.display = 'none';
  }

  openModal('modal-cliente');
}
function abrirClienteDoPedido(id) {
  const p = load(K.P).find(x => x.id === id);
  if (!p) { showToast('Pedido não encontrado.'); return; }
  const key = (p.clienteId && load(K.CLI).some(c => c.id === p.clienteId)) ? 'cli:' + p.clienteId : 'legacy:' + getClienteKey(p);
  closeModal('modal-detalhe');
  openClienteDetail(key);
}
function gerarMsgFidelizacao(c) {
  const linhas = [
    `Oi ${c.nome || ''}! 🎀`,
    '',
    'Obrigada por confiar no meu trabalho durante todo esse tempo.',
    'É um prazer poder registrar momentos tão importantes para você e sua família.',
    `Esse mimo é uma pequena forma de agradecer pela sua fidelidade — já são ${c.qtdPedidos} pedido${c.qtdPedidos===1?'':'s'} juntas. 💛`
  ];
  return linhas.join('\n');
}
function enviarMsgFidelizacao() {
  const c = aggregateClientes().find(x => x.key === currentClienteKey);
  if (!c) return;
  const wa = c.whatsapp ? `https://wa.me/55${c.whatsapp.replace(/\D/g, '')}` : null;
  abrirModalMsg('💌 Mensagem de fidelização', gerarMsgFidelizacao(c), wa);
}
function openPedidoModal(p=null) {
  document.getElementById('modal-pedido-title').textContent = p ? 'Editar pedido' : 'Novo pedido';
  const set = (id, val) => { document.getElementById(id).value = val||''; };
  set('pedido-id', p?.id); set('p-nome',p?.nome); set('p-whatsapp',p?.whatsapp);
  set('p-cliente-id', p?.clienteId);
  populateClienteSelectPedido(p?.clienteId);
  document.getElementById('p-status').value = p?.status||'Novo';
  set('p-produtos',p?.produtos);
  set('p-qtd',p?.qtd||1); set('p-total',p?.total); set('p-pago',p?.pago);
  set('p-pendente',p?.pendente); set('p-data-evento',p?.dataEvento);
  set('p-data-entrega',p?.dataEntrega); set('p-obs',p?.obs);
  set('p-custos-extras',p?.custosExtras); set('p-custos-extras-desc',p?.custosExtrasDesc);
  // foto
  const fotoUrl = p?.fotoUrl||''
  set('p-foto-url', fotoUrl);
  document.getElementById('p-foto-input').value = '';
  if (fotoUrl) {
    document.getElementById('upload-img').src = fotoUrl;
    document.getElementById('upload-preview').style.display = 'block';
    document.getElementById('upload-placeholder').style.display = 'none';
  } else {
    document.getElementById('upload-preview').style.display = 'none';
    document.getElementById('upload-placeholder').style.display = 'block';
  }
  itensPedidoAtual = p?.itens ? JSON.parse(JSON.stringify(p.itens)) : [];
  populateProdutoSelectPedido();
  renderItensPedidoList();
  openModal('modal-pedido');
}

// Compress image using canvas before upload (quality 0.9 = 90%)
function savePedido() {
  const nome        = document.getElementById('p-nome').value.trim();
  const dataEntrega = document.getElementById('p-data-entrega').value;
  if (!nome) { showToast('Informe o nome do cliente'); return; }
  const id    = document.getElementById('pedido-id').value || 'p'+Date.now();
  const total = parseFloat(document.getElementById('p-total').value)||0;
  const pago  = parseFloat(document.getElementById('p-pago').value)||0;
  const statusNovo = document.getElementById('p-status').value;
  const ps  = load(K.P);
  const idx = ps.findIndex(p=>p.id===id);
  const existente = idx>=0 ? ps[idx] : null;
  const agora = new Date().toISOString();
  const obj   = {
    id, nome, dataEntrega,
    criado:      existente?.criado || agora,
    statusDesde: (existente && existente.status===statusNovo) ? (existente.statusDesde || existente.criado || agora) : agora,
    clienteId: document.getElementById('p-cliente-id').value || '',
    whatsapp:  document.getElementById('p-whatsapp').value,
    status:    statusNovo,
    produtos:  document.getElementById('p-produtos').value,
    qtd:       parseInt(document.getElementById('p-qtd').value)||1,
    total, pago, pendente: Math.max(0,total-pago),
    dataEvento:document.getElementById('p-data-evento').value,
    obs:       document.getElementById('p-obs').value,
    fotoUrl:   document.getElementById('p-foto-url').value,
    itens:     itensPedidoAtual,
    custosExtras:     parseFloat(document.getElementById('p-custos-extras').value)||0,
    custosExtrasDesc: document.getElementById('p-custos-extras-desc').value,
    alertaSnoozeAte:  existente?.alertaSnoozeAte  || '',
    alertaSnoozeTipo: existente?.alertaSnoozeTipo || '',
  };
  if (idx>=0) ps[idx]=obj; else ps.push(obj);
  save(K.P, ps);
  aplicarConsumoEstoque(existente?.itens, itensPedidoAtual);
  closeModal('modal-pedido');
  currentScreen==='pedidos' ? filterPedidos() : renderDashboard();
  showToast('Pedido salvo.');
}
/* ── PRODUTOS (catálogo) ──────────────────────────── */
function renderProdutosScreen(){
  const el = document.getElementById('produtos-content');
  const prods = load(K.PR);
  el.innerHTML = prods.length ? prods.map(p=>produtoCardHTML(p)).join('') : emptyHTML('Nenhum produto cadastrado.<br><strong>Toque no + para adicionar.</strong>');
}
/* ── ESTOQUE (materiais + relatório) ─────────────── */
function renderEstoqueScreen(){ renderEstoqueContent(estoqueTab); }
function setEstoqueTab(el){
  document.querySelectorAll('#screen-estoque .tab').forEach(t=>t.classList.remove('active'));
  el.classList.add('active'); estoqueTab = el.dataset.tab; renderEstoqueContent(estoqueTab);
}
function renderEstoqueContent(tab){
  const el = document.getElementById('estoque-content');
  if (tab==='materiais'){
    const mats = load(K.M);
    const btnEntrada = `<button class="btn btn-ghost" style="width:100%;margin-bottom:14px" onclick="openEstoqueEntradaModal()">
      📦 Comprei mais material (dar entrada no estoque)
    </button>`;
    el.innerHTML = btnEntrada + (mats.length ? mats.map(m=>materialCardHTML(m)).join('') : emptyHTML('Nenhum material cadastrado.<br><strong>Toque no + para adicionar.</strong>'));
  } else {
    el.innerHTML = renderNiveisEstoque();
    filterNiveis();
  }
}

// Classifica o nível de estoque de um material em boa quantidade / acabando / baixo / crítico.
// Quando o material tem um estoque mínimo cadastrado, usa ele como referência relativa
// (2x o mínimo ou mais = boa; entre 1x e 2x = acabando; entre 0.5x e 1x = baixo; abaixo = crítico).
// Sem estoque mínimo cadastrado, cai para faixas fixas gerais como aproximação.
function renderNiveisEstoque(){
  const mats = load(K.M);
  if (!mats.length) return `<div class="card">${emptyHTML('Nenhum material cadastrado.<br><strong>Cadastre materiais na aba Materiais.</strong>')}</div>`;

  const contagem = { boa:0, acabando:0, baixo:0, critico:0 };
  mats.forEach(m=>{ contagem[statusEstoqueMaterial(m).tier]++; });

  return `
    <div class="fin-grid">
      <div class="fin-tile"><div class="fin-tile-label">Boa quantidade</div><div class="fin-tile-value green">${contagem.boa}</div></div>
      <div class="fin-tile"><div class="fin-tile-label">Acabando</div><div class="fin-tile-value" style="color:#C0701A">${contagem.acabando}</div></div>
      <div class="fin-tile"><div class="fin-tile-label">Baixo</div><div class="fin-tile-value red">${contagem.baixo}</div></div>
      <div class="fin-tile"><div class="fin-tile-label">Crítico</div><div class="fin-tile-value red">${contagem.critico}</div></div>
    </div>
    <div class="search-wrap">
      <svg viewBox="0 0 24 24"><circle cx="11" cy="11" r="8"/><path d="m21 21-4.35-4.35"/></svg>
      <input type="text" placeholder="Buscar material..." id="search-niveis" oninput="filterNiveis()">
    </div>
    <div id="niveis-list"></div>
    <div style="font-size:11px;color:var(--text-soft);text-align:center;margin-top:10px">
      🟢 boa quantidade (2x+ o mínimo) · 🟡 acabando (entre 1x e 2x o mínimo) · 🔴 baixo/crítico (abaixo do mínimo)<br>
      Materiais sem estoque mínimo cadastrado usam faixas gerais (100/50/20 unidades) como aproximação.
    </div>
  `;
}

// Filtra e (re)renderiza apenas a lista de materiais dentro da tela de Níveis,
// mantendo o campo de busca e os cartões de resumo intactos (sem perder o foco a cada tecla)
function filterNiveis(){
  const el = document.getElementById('niveis-list');
  if (!el) return;
  const q = (document.getElementById('search-niveis')?.value || '').toLowerCase();
  const mats = [...load(K.M)]
    .filter(m => !q || (m.nome||'').toLowerCase().includes(q))
    .sort((a,b)=>(a.nome||'').localeCompare(b.nome||'','pt-BR'));

  if (!mats.length){ el.innerHTML = emptyHTML('Nenhum material encontrado.'); return; }

  el.innerHTML = `
    <div class="card" style="padding:4px 20px">
      ${mats.map(m=>{
        const s = statusEstoqueMaterial(m);
        return `
        <div class="tx-row">
          <div class="tx-left" onclick="openMaterialById('${m.id}')" style="cursor:pointer">
            <div style="width:10px;height:10px;border-radius:50%;background:${s.cor};flex-shrink:0"></div>
            <div>
              <div class="tx-desc">${m.nome}</div>
              <div class="tx-date">${m.estoque||0} ${m.unidade||''}${m.estoqueMin?' · mín. '+m.estoqueMin+' '+(m.unidade||''):''}</div>
            </div>
          </div>
          <div style="display:flex;align-items:center;gap:8px;flex-shrink:0">
            <span class="badge" style="background:${s.bg};color:${s.cor};border-color:${s.border}">${s.label}</span>
            <button class="btn btn-ghost btn-sm" onclick="openEstoqueEntradaModal('${m.id}')">+ Entrada</button>
          </div>
        </div>`;
      }).join('')}
    </div>`;
}

// Custo de uma composição (lista de {matId, qtd}) com base no custo unitário atual de cada material
function produtoCardHTML(p){
  const custo  = custoComposicao(p.composicao);
  const margem = (p.preco||0) - custo;
  const ativo  = p.status !== 'Inativo';
  return `
  <div class="pedido-card" onclick="openProdutoById('${p.id}')">
    <div class="pedido-card-header">
      <div>
        <div class="pedido-nome">${p.nome}</div>
        <div class="pedido-sub">${p.categoria||'—'}${p.composicao&&p.composicao.length?' · '+p.composicao.length+' material(is)':' · sem composição fixa'}</div>
      </div>
      <span class="badge ${ativo?'badge-pronto':'badge-cancelado'}">${ativo?'Ativo':'Inativo'}</span>
    </div>
    <div class="pedido-meta">
      <span class="pedido-meta-item">Venda: ${fmtM(p.preco)}</span>
      <span class="pedido-meta-item">Custo: ${fmtM(custo)}</span>
      <span class="pedido-meta-item" style="color:${margem>=0?'var(--success)':'var(--danger)'};font-weight:600">Margem: ${fmtM(margem)}</span>
      <button class="btn btn-ghost btn-sm" style="margin-left:auto" onclick="event.stopPropagation();deleteProduto('${p.id}')">Excluir</button>
    </div>
  </div>`;
}
function materialCardHTML(m){
  const baixo = (m.estoqueMin||0) > 0 && (m.estoque||0) <= (m.estoqueMin||0);
  return `
  <div class="pedido-card" onclick="openMaterialById('${m.id}')">
    <div class="pedido-card-header">
      <div>
        <div class="pedido-nome">${m.nome}</div>
        <div class="pedido-sub">${m.unidade||'unidade'} · custo unit.: ${fmtM(m.custo)}</div>
      </div>
      ${baixo?'<span class="badge badge-cancelado">Estoque baixo</span>':''}
    </div>
    <div class="pedido-meta">
      <span class="pedido-meta-item">Estoque atual: ${m.estoque||0} ${m.unidade||''}</span>
      <div style="margin-left:auto;display:flex;gap:6px;flex-wrap:wrap">
        ${m.link?`<button class="btn btn-ghost btn-sm" onclick="event.stopPropagation();window.open('${m.link}','_blank')">🔗 Ver produto</button>`:''}
        <button class="btn btn-ghost btn-sm" onclick="event.stopPropagation();openEstoqueEntradaModal('${m.id}')">+ Entrada</button>
        <button class="btn btn-ghost btn-sm" onclick="event.stopPropagation();deleteMaterial('${m.id}')">Excluir</button>
      </div>
    </div>
  </div>`;
}
function openProdutoById(id){ const p = load(K.PR).find(x=>x.id===id); if(p) openProdutoModal(p); }
function openMaterialById(id){ const m = load(K.M).find(x=>x.id===id); if(m) openMaterialModal(m); }
function populateCategoriaSelect(selected){
  const cats = getCategoriasProdutos();
  const sel = document.getElementById('pr-categoria');
  sel.innerHTML = cats.map(c=>`<option value="${c}">${c}</option>`).join('')
    + '<option value="__new__">➕ Adicionar nova categoria...</option>';
  sel.value = selected && cats.includes(selected) ? selected : (cats[0] || '');
}
function onCategoriaSelectChange(sel){
  if (sel.value === '__new__'){
    const primeiraValida = Array.from(sel.options).find(o=>o.value && o.value !== '__new__');
    sel.value = primeiraValida ? primeiraValida.value : '';
    openCategoriaQuick();
  }
}
function openCategoriaQuick(){
  document.getElementById('catq-nome').value = '';
  openModal('modal-categoria-quick');
  setTimeout(()=>document.getElementById('catq-nome')?.focus(), 250);
}
function saveCategoriaQuick(){
  const nome = document.getElementById('catq-nome').value.trim();
  if (!nome){ showToast('Informe o nome da categoria'); return; }
  appConfig = loadO(K.C);
  const cats = getCategoriasProdutos();
  if (!cats.includes(nome)) cats.push(nome);
  appConfig.categoriasProdutos = cats;
  save(K.C, appConfig);
  closeModal('modal-categoria-quick');
  populateCategoriaSelect(nome);
  showToast('Categoria cadastrada! Já selecionada.');
}
/* -- Produto: modal e composição -- */
function openProdutoModal(p=null){
  document.getElementById('modal-produto-title').textContent = p ? 'Editar produto' : 'Novo produto';
  document.getElementById('pr-id').value        = p?.id || '';
  document.getElementById('pr-nome').value      = p?.nome || '';
  populateCategoriaSelect(p?.categoria);
  document.getElementById('pr-status').value    = p?.status || 'Ativo';
  document.getElementById('pr-desc').value      = p?.descricao || '';
  document.getElementById('pr-preco').value     = p?.preco || '';
  composicaoAtual = p?.composicao ? JSON.parse(JSON.stringify(p.composicao)) : [];
  populateMaterialSelect();
  renderComposicaoList();
  openModal('modal-produto');
}
function populateMaterialSelect(){
  const mats = load(K.M);
  const sel = document.getElementById('pr-comp-mat');
  sel.innerHTML = (mats.length
    ? mats.map(m=>`<option value="${m.id}">${m.nome} (${fmtM(m.custo)}/${m.unidade||'un'})</option>`).join('')
    : '<option value="">Cadastre um material primeiro</option>')
    + '<option value="__new__">➕ Cadastrar novo material...</option>';
}
function renderComposicaoList(){
  const mats = load(K.M);
  const el = document.getElementById('pr-comp-list');
  el.innerHTML = composicaoAtual.length ? composicaoAtual.map((c,i)=>{
    const m = mats.find(x=>x.id===c.matId);
    return `<div class="tx-row" style="padding:8px 0">
      <div class="tx-left"><div style="font-size:13px">${m?m.nome:'Material removido'} — ${c.qtd} ${m?.unidade||''}</div></div>
      <div style="display:flex;align-items:center;gap:8px">
        <span style="font-size:12px;color:var(--text-soft)">${fmtM(m?(m.custo*c.qtd):0)}</span>
        <button class="btn btn-ghost btn-sm" onclick="removeComposicaoItem(${i})">Remover</button>
      </div>
    </div>`;
  }).join('') : '<div style="font-size:12px;color:var(--text-soft)">Nenhum material adicionado ainda.</div>';
  renderComposicaoResumo();
}

// Calcula quanto de um material é realmente consumido por UNIDADE do produto, quando
// esse material rende várias unidades de uma vez (ex: 1 folha impressa rende 12 bottons).
// Faz Qtd usada ÷ Rende e preenche o campo "Qtd por unidade" já com o valor correto.
function addComposicaoItem(){
  const matId = document.getElementById('pr-comp-mat').value;
  const qtd   = parseFloat(document.getElementById('pr-comp-qtd').value);
  if (!matId){ showToast('Cadastre um material primeiro'); return; }
  if (!qtd || qtd<=0){ showToast('Informe a quantidade'); return; }
  const idx = composicaoAtual.findIndex(c=>c.matId===matId);
  if (idx>=0) composicaoAtual[idx].qtd += qtd; else composicaoAtual.push({ matId, qtd });
  document.getElementById('pr-comp-qtd').value = '';
  document.getElementById('pr-comp-rende-usado').value = '';
  document.getElementById('pr-comp-rende-qtd').value = '';
  renderComposicaoList();
}
function removeComposicaoItem(i){ composicaoAtual.splice(i,1); renderComposicaoList(); }
function renderComposicaoResumo(){
  const custo = custoComposicao(composicaoAtual);
  const preco = parseFloat(document.getElementById('pr-preco').value)||0;
  document.getElementById('pr-custo-preview').textContent = fmtM(custo);
  document.getElementById('pr-preco-preview').textContent = fmtM(preco);
  const margem = preco-custo;
  const mEl = document.getElementById('pr-margem-preview');
  mEl.textContent = fmtM(margem);
  mEl.style.color = margem>=0 ? 'var(--success)' : 'var(--danger)';
}
function saveProduto(){
  const nome  = document.getElementById('pr-nome').value.trim();
  const preco = parseFloat(document.getElementById('pr-preco').value)||0;
  if (!nome){ showToast('Informe o nome do produto'); return; }
  const id = document.getElementById('pr-id').value || 'pr'+Date.now();
  const custo = custoComposicao(composicaoAtual);
  const obj = {
    id, nome,
    categoria:  document.getElementById('pr-categoria').value.trim(),
    status:     document.getElementById('pr-status').value,
    descricao:  document.getElementById('pr-desc').value,
    preco,
    composicao: composicaoAtual,
    custoEstimado: custo,
    margem: preco-custo
  };
  const prs = load(K.PR);
  const idx = prs.findIndex(p=>p.id===id);
  if (idx>=0) prs[idx]=obj; else prs.push(obj);
  save(K.PR, prs);
  closeModal('modal-produto');
  renderProdutosScreen();
  showToast('Produto salvo.');
}
function deleteProduto(id){
  if (!confirm('Excluir este produto?')) return;
  fbDel('produtos_catalogo', id);
  save(K.PR, load(K.PR).filter(p=>p.id!==id));
  renderProdutosScreen();
  showToast('Produto excluído.');
}
/* -- Material (estoque): modal -- */
function openMaterialModal(m=null){
  document.getElementById('modal-material-title').textContent = m?'Editar material':'Novo material';
  document.getElementById('mat-id').value           = m?.id || '';
  document.getElementById('mat-nome').value         = m?.nome || '';
  document.getElementById('mat-unidade').value      = m?.unidade || 'unidade';
  document.getElementById('mat-custo').value        = m?.custo ?? '';
  document.getElementById('mat-estoque').value      = m?.estoque ?? '';
  document.getElementById('mat-estoque-min').value  = m?.estoqueMin ?? '';
  document.getElementById('mat-link').value         = m?.link || '';
  document.getElementById('mat-pacote-valor').value = '';
  document.getElementById('mat-pacote-qtd').value   = '';
  renderMatHistorico(m?.id);
  openModal('modal-material');
}
function renderMatHistorico(matId){
  const el = document.getElementById('mat-historico');
  if (!matId){ el.innerHTML=''; return; }
  const movs = load(K.EM).filter(x=>x.matId===matId).sort((a,b)=>b.data.localeCompare(a.data));
  if (!movs.length){
    el.innerHTML = `<div class="card-label" style="margin-top:18px">Histórico de movimentação</div><div style="font-size:12px;color:var(--text-soft);margin-bottom:10px">Nenhuma movimentação registrada ainda.</div>`;
    return;
  }
  const totalEntradas = movs.filter(m=>m.tipo==='entrada').reduce((s,m)=>s+(m.valor||0),0);
  const totalSaidas   = movs.filter(m=>m.tipo==='saida').reduce((s,m)=>s+(m.valor||0),0);
  el.innerHTML = `
    <div class="card-label" style="margin-top:18px">Histórico de movimentação</div>
    <div class="fin-grid" style="margin-bottom:10px">
      <div class="fin-tile"><div class="fin-tile-label">Total comprado</div><div class="fin-tile-value green" style="font-size:16px">${fmtM(totalEntradas)}</div></div>
      <div class="fin-tile"><div class="fin-tile-label">Total consumido</div><div class="fin-tile-value red" style="font-size:16px">${fmtM(totalSaidas)}</div></div>
    </div>
    <div style="max-height:220px;overflow-y:auto">
      ${movs.map(m=>`
        <div class="tx-row" style="padding:8px 0">
          <div class="tx-left">
            <div class="tx-dot ${m.tipo==='entrada'?'in':'out'}">
              <svg viewBox="0 0 24 24">${m.tipo==='entrada'?'<polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/>':'<polyline points="23 18 13.5 8.5 8.5 13.5 1 6"/><polyline points="17 18 23 18 23 12"/>'}</svg>
            </div>
            <div><div class="tx-desc" style="font-size:13px">${m.tipo==='entrada'?'Entrada':'Saída'} · ${m.qtd} un.</div><div class="tx-date">${formatDate(m.data)}${m.motivo?' · '+m.motivo:''}</div></div>
          </div>
          <div class="tx-amount ${m.tipo==='entrada'?'in':'out'}" style="font-size:13px">${m.tipo==='entrada'?'+':'-'}${fmtM(m.valor)}</div>
        </div>`).join('')}
    </div>`;
}
function saveMaterial(){
  const nome  = document.getElementById('mat-nome').value.trim();
  const custo = parseFloat(document.getElementById('mat-custo').value);
  if (!nome){ showToast('Informe o nome do material'); return; }
  if (isNaN(custo)){ showToast('Informe o custo unitário'); return; }
  const id = document.getElementById('mat-id').value || 'mat'+Date.now();
  const obj = {
    id, nome,
    unidade: document.getElementById('mat-unidade').value,
    custo,
    estoque:    parseFloat(document.getElementById('mat-estoque').value)||0,
    estoqueMin: parseFloat(document.getElementById('mat-estoque-min').value)||0,
    link:       document.getElementById('mat-link').value.trim()
  };
  const ms = load(K.M);
  const idx = ms.findIndex(x=>x.id===id);
  if (idx>=0) ms[idx]=obj; else ms.push(obj);
  save(K.M, ms);
  closeModal('modal-material');
  renderEstoqueContent(estoqueTab);
  showToast('Material salvo.');
}
function deleteMaterial(id){
  if (!confirm('Excluir este material? Produtos que o utilizam deixarão de calcular esse custo.')) return;
  fbDel('materiais', id);
  save(K.M, load(K.M).filter(m=>m.id!==id));
  renderEstoqueContent(estoqueTab);
  showToast('Material excluído.');
}
/* -- Cadastro rápido de material (atalho a partir de outros selects) -- */
let _matQuickTarget = null; // guarda qual select disparou o atalho: 'pr-comp-mat' ou 'ee-mat'
function onMaterialSelectChange(sel){
  if (sel.value === '__new__') {
    _matQuickTarget = sel.id;
    // volta o select para um valor válido, para não deixar "__new__" selecionado se o usuário cancelar
    const primeiraOpcaoValida = Array.from(sel.options).find(o => o.value && o.value !== '__new__');
    sel.value = primeiraOpcaoValida ? primeiraOpcaoValida.value : '';
    openMaterialQuick();
    return;
  }
  if (sel.id === 'ee-mat') onEeMatChange();
}
function openMaterialQuick(){
  document.getElementById('mq-nome').value = '';
  document.getElementById('mq-unidade').value = 'unidade';
  document.getElementById('mq-custo').value = '';
  document.getElementById('mq-estoque').value = '';
  document.getElementById('mq-pacote-valor').value = '';
  document.getElementById('mq-pacote-qtd').value = '';
  openModal('modal-material-quick');
  setTimeout(()=>document.getElementById('mq-nome')?.focus(), 250);
}
function saveMaterialQuick(){
  const nome  = document.getElementById('mq-nome').value.trim();
  const custo = parseFloat(document.getElementById('mq-custo').value);
  if (!nome){ showToast('Informe o nome do material'); return; }
  if (isNaN(custo) || custo<0){ showToast('Informe o custo unitário'); return; }
  const id = 'mat'+Date.now();
  const obj = {
    id, nome,
    unidade: document.getElementById('mq-unidade').value,
    custo,
    estoque: parseFloat(document.getElementById('mq-estoque').value)||0,
    estoqueMin: 0
  };
  const ms = load(K.M);
  ms.push(obj);
  save(K.M, ms);
  closeModal('modal-material-quick');

  // Repopula o select de origem e já seleciona o material recém-criado, sem fechar o modal em que a pessoa estava
  if (_matQuickTarget === 'pr-comp-mat') {
    populateMaterialSelect();
    document.getElementById('pr-comp-mat').value = id;
  } else if (_matQuickTarget === 'ee-mat') {
    const sel = document.getElementById('ee-mat');
    sel.innerHTML = ms.map(m=>`<option value="${m.id}">${m.nome} (${m.unidade||'un'})</option>`).join('')
      + '<option value="__new__">➕ Cadastrar novo material...</option>';
    sel.value = id;
    onEeMatChange();
  }
  _matQuickTarget = null;
  showToast('Material cadastrado! Já selecionado.');
}
/* -- Entrada de estoque (compra de material) -- */
function openEstoqueEntradaModal(matId){
  const mats = load(K.M);
  const sel = document.getElementById('ee-mat');
  sel.innerHTML = (mats.length
    ? mats.map(m=>`<option value="${m.id}">${m.nome} (${m.unidade||'un'})</option>`).join('')
    : '<option value="">Cadastre um material primeiro</option>')
    + '<option value="__new__">➕ Cadastrar novo material...</option>';
  if (matId) sel.value = matId;
  document.getElementById('ee-qtd').value = '';
  document.getElementById('ee-valor-total').value = '';
  document.getElementById('ee-calc-preview').textContent = '';
  document.getElementById('ee-data').value = todayStr();
  document.getElementById('ee-obs').value = '';
  onEeMatChange();
  openModal('modal-estoque-entrada');
}

// Calcula o custo por unidade a partir do preço do pacote e da quantidade de unidades nele
// prefix: 'mat' (Novo material), 'mq' (Cadastro rápido) ou 'ee' (Entrada de estoque) — todos usam o padrão {prefix}-pacote-valor / {prefix}-pacote-qtd / {prefix}-custo
function onEeQtdOuValorChange(){
  const qtd   = parseFloat(document.getElementById('ee-qtd').value) || 0;
  const total = parseFloat(document.getElementById('ee-valor-total').value) || 0;
  const preview = document.getElementById('ee-calc-preview');
  if (qtd > 0 && total > 0) {
    const custoUnit = total / qtd;
    document.getElementById('ee-custo').value = custoUnit.toFixed(4);
    preview.textContent = `= ${fmtM(custoUnit)} por unidade`;
  } else {
    preview.textContent = '';
  }
  updateEeTotalPreview();
}
function onEeMatChange(){
  const matId = document.getElementById('ee-mat').value;
  const m = load(K.M).find(x=>x.id===matId);
  document.getElementById('ee-custo').value = m ? (m.custo ?? '') : '';
  document.getElementById('ee-valor-total').value = '';
  document.getElementById('ee-calc-preview').textContent = '';
  updateEeTotalPreview();
}
function updateEeTotalPreview(){
  const qtd = parseFloat(document.getElementById('ee-qtd').value)||0;
  const custo = parseFloat(document.getElementById('ee-custo').value)||0;
  document.getElementById('ee-total-preview').textContent = fmtM(qtd*custo);
}
function saveEstoqueEntrada(){
  const matId = document.getElementById('ee-mat').value;
  const qtd   = parseFloat(document.getElementById('ee-qtd').value);
  const custo = parseFloat(document.getElementById('ee-custo').value);
  const data  = document.getElementById('ee-data').value || todayStr();
  const obs   = document.getElementById('ee-obs').value.trim();
  if (!matId){ showToast('Selecione um material'); return; }
  if (!qtd || qtd<=0){ showToast('Informe a quantidade comprada'); return; }
  if (isNaN(custo) || custo<0){ showToast('Informe o custo unitário'); return; }

  const ms = load(K.M);
  const idx = ms.findIndex(m=>m.id===matId);
  if (idx<0){ showToast('Material não encontrado'); return; }
  ms[idx].estoque = (ms[idx].estoque||0) + qtd;
  ms[idx].custo = custo; // atualiza para o custo da compra mais recente
  save(K.M, ms);

  const em = load(K.EM);
  em.push({
    id: 'em'+Date.now(),
    matId, tipo: 'entrada', qtd, custoUnit: custo, valor: qtd*custo,
    data, motivo: obs || 'Compra de material'
  });
  save(K.EM, em);

  closeModal('modal-estoque-entrada');
  if (currentScreen === 'estoque') renderEstoqueContent(estoqueTab);
  else renderDashboard();
  showToast('Entrada de estoque registrada.');
}
/* -- Itens de catálogo dentro de um pedido -- */
function populateProdutoSelectPedido(){
  const prods = load(K.PR).filter(p=>p.status!=='Inativo');
  const sel = document.getElementById('p-item-produto');
  sel.innerHTML = prods.length
    ? prods.map(p=>`<option value="${p.id}">${p.nome} (${fmtM(p.preco)})</option>`).join('')
    : '<option value="">Nenhum produto ativo cadastrado</option>';
}
function addItemPedido(){
  const prodId = document.getElementById('p-item-produto').value;
  const qtd    = parseFloat(document.getElementById('p-item-qtd').value)||1;
  if (!prodId){ showToast('Cadastre um produto no catálogo primeiro'); return; }
  const prod = load(K.PR).find(p=>p.id===prodId);
  if (!prod) return;
  const idx = itensPedidoAtual.findIndex(i=>i.produtoId===prodId);
  if (idx>=0) itensPedidoAtual[idx].qtd += qtd;
  else itensPedidoAtual.push({ produtoId: prodId, produtoNome: prod.nome, qtd, precoUnit: prod.preco||0 });
  document.getElementById('p-item-qtd').value = 1;
  renderItensPedidoList();
}
function removeItemPedido(i){ itensPedidoAtual.splice(i,1); renderItensPedidoList(); }
function renderItensPedidoList(){
  const el = document.getElementById('p-itens-list');
  el.innerHTML = itensPedidoAtual.length ? itensPedidoAtual.map((it,i)=>`
    <div class="tx-row" style="padding:8px 0">
      <div class="tx-left"><div style="font-size:13px">${it.qtd}x ${it.produtoNome}</div></div>
      <div style="display:flex;align-items:center;gap:8px">
        <span style="font-size:12px;color:var(--text-soft)">${fmtM(it.precoUnit*it.qtd)}</span>
        <button class="btn btn-ghost btn-sm" onclick="removeItemPedido(${i})">Remover</button>
      </div>
    </div>`).join('') : '<div style="font-size:12px;color:var(--text-soft)">Nenhum item do catálogo adicionado.</div>';
  renderItensPedidoResumo();
}

// Calcula, para uma lista de itens {produtoId, qtd}, o total de cada material consumido (proporcional à quantidade)
function renderItensPedidoResumo(){
  const wrap = document.getElementById('p-itens-resumo');
  if (!itensPedidoAtual.length){ wrap.style.display='none'; return; }
  wrap.style.display='block';
  const totalVenda = itensPedidoAtual.reduce((s,i)=>s+i.precoUnit*i.qtd,0);
  const { detalhes, custoTotal } = calcMateriaisItens(itensPedidoAtual);
  const extras = parseFloat(document.getElementById('p-custos-extras')?.value)||0;
  const lucro = totalVenda - custoTotal - extras;
  const margem = totalVenda>0 ? (lucro/totalVenda*100) : 0;
  const totalPedido = parseFloat(document.getElementById('p-total')?.value)||0;
  const divergente = totalPedido>0 && Math.abs(totalPedido-totalVenda)>0.01;
  wrap.innerHTML = `
    <div class="meta-row"><span>Valor total dos itens</span><b>${fmtM(totalVenda)}</b></div>
    <div class="meta-row"><span>Custo estimado dos materiais</span><b>${fmtM(custoTotal)}</b></div>
    ${extras?`<div class="meta-row"><span>Outros custos informados</span><b>${fmtM(extras)}</b></div>`:''}
    <div class="meta-row"><span>Lucro bruto estimado</span><b style="color:${lucro>=0?'var(--success)':'var(--danger)'}">${fmtM(lucro)}</b></div>
    <div class="meta-row"><span>Margem de lucro estimada</span><b style="color:${margem>=0?'var(--success)':'var(--danger)'}">${margem.toFixed(1)}%</b></div>
    ${detalhes.length?`<div style="margin-top:8px;font-size:11px;color:var(--text-soft)">Materiais a consumir do estoque: ${detalhes.map(d=>`${d.nome} (${d.qtd} ${d.unidade})`).join(', ')}</div>`:''}
    ${divergente?`<div style="margin-top:10px;padding:8px 10px;background:var(--rose-pale);border:1px solid var(--rose-light);border-radius:8px;font-size:11px;color:var(--rose-dark)">⚠️ O valor total do pedido (${fmtM(totalPedido)}) é diferente do valor dos itens do catálogo (${fmtM(totalVenda)}). O lucro em "Financeiro do pedido" e em "Lucratividade" usa o valor total do pedido.</div>`:''}
    <button type="button" class="btn btn-ghost btn-sm" style="width:100%;margin-top:10px" onclick="usarValorItensNoPedido()">Usar este valor como total do pedido</button>
  `;
}
function usarValorItensNoPedido(){
  const totalVenda = itensPedidoAtual.reduce((s,i)=>s+i.precoUnit*i.qtd,0);
  document.getElementById('p-total').value = totalVenda.toFixed(2);
  calcPendente();
  showToast('Valor total atualizado.');
}

// Registra uma movimentação de estoque (entrada = compra/ajuste positivo, saida = consumo/ajuste negativo)
/* -- Relatório de estoque e insumos -- */
function renderRelatorioEstoque(){
  const movs = load(K.EM);
  const mats = load(K.M);
  const now = new Date();
  const mesAtual = `${now.getFullYear()}-${String(now.getMonth()+1).padStart(2,'0')}`;

  const entradas = movs.filter(m=>m.tipo==='entrada');
  const saidas   = movs.filter(m=>m.tipo==='saida');
  const totalInvestido   = entradas.reduce((s,m)=>s+(m.valor||0),0);
  const totalConsumido   = saidas.reduce((s,m)=>s+(m.valor||0),0);
  const investidoMes = entradas.filter(m=>m.data.startsWith(mesAtual)).reduce((s,m)=>s+(m.valor||0),0);
  const consumidoMes = saidas.filter(m=>m.data.startsWith(mesAtual)).reduce((s,m)=>s+(m.valor||0),0);

  // Ranking de materiais mais consumidos (por valor)
  const porMaterial = {};
  saidas.forEach(m=>{
    if (!porMaterial[m.matId]) porMaterial[m.matId] = { qtd:0, valor:0 };
    porMaterial[m.matId].qtd   += m.qtd||0;
    porMaterial[m.matId].valor += m.valor||0;
  });
  const ranking = Object.entries(porMaterial)
    .map(([matId,d])=>({ matId, nome: mats.find(x=>x.id===matId)?.nome || 'Material removido', unidade: mats.find(x=>x.id===matId)?.unidade || '', ...d }))
    .sort((a,b)=>b.valor-a.valor)
    .slice(0,10);

  // Valor total em estoque parado (custo unitário atual x estoque atual)
  const valorEstoqueAtual = mats.reduce((s,m)=>s+((m.custo||0)*(m.estoque||0)),0);

  const alertasEstoqueBaixo = mats.filter(m=>(m.estoqueMin||0)>0 && (m.estoque||0)<=(m.estoqueMin||0));

  if (!movs.length && !mats.length){
    return `<div class="card">${emptyHTML('Nenhum dado de estoque ainda.<br><strong>Cadastre materiais e registre entradas.</strong>')}</div>`;
  }

  return `
    <div class="fin-grid">
      <div class="fin-tile"><div class="fin-tile-label">Investido (total)</div><div class="fin-tile-value green">${fmtM(totalInvestido)}</div></div>
      <div class="fin-tile"><div class="fin-tile-label">Consumido (total)</div><div class="fin-tile-value red">${fmtM(totalConsumido)}</div></div>
      <div class="fin-tile"><div class="fin-tile-label">Investido (mês)</div><div class="fin-tile-value blue">${fmtM(investidoMes)}</div></div>
      <div class="fin-tile"><div class="fin-tile-label">Consumido (mês)</div><div class="fin-tile-value gold">${fmtM(consumidoMes)}</div></div>
    </div>

    <div class="card">
      <div class="card-label">Valor parado em estoque hoje</div>
      <div style="font-family:var(--font-display);font-size:26px;font-weight:600;color:var(--text)">${fmtM(valorEstoqueAtual)}</div>
      <div style="font-size:12px;color:var(--text-soft);margin-top:4px">Estoque atual de cada material × custo unitário cadastrado.</div>
    </div>

    ${alertasEstoqueBaixo.length ? `
    <div class="card" style="border-color:var(--danger)">
      <div class="card-label" style="color:var(--danger)">⚠️ Estoque baixo</div>
      ${alertasEstoqueBaixo.map(m=>`
        <div class="tx-row">
          <div class="tx-left"><div class="tx-desc">${m.nome}</div></div>
          <div style="text-align:right">
            <div style="font-size:13px;color:var(--danger);font-weight:600">${m.estoque||0} ${m.unidade||''}</div>
            <div style="font-size:11px;color:var(--text-soft)">mín. ${m.estoqueMin} ${m.unidade||''}</div>
          </div>
        </div>`).join('')}
    </div>` : ''}

    <div class="card">
      <div class="card-label">Insumos mais utilizados</div>
      ${ranking.length ? ranking.map((r,i)=>`
        <div class="tx-row">
          <div class="tx-left">
            <div style="width:22px;height:22px;border-radius:6px;background:var(--blue-pale);display:flex;align-items:center;justify-content:center;font-size:11px;font-weight:700;color:var(--blue-dark)">${i+1}</div>
            <div><div class="tx-desc">${r.nome}</div><div class="tx-date">${r.qtd} ${r.unidade} consumidos</div></div>
          </div>
          <div class="tx-amount out">${fmtM(r.valor)}</div>
        </div>`).join('') : '<div style="font-size:12px;color:var(--text-soft)">Nenhum consumo registrado ainda.</div>'}
    </div>
  `;
}
/* ── AGENDA ──────────────────────────────────────── */
function renderCalendar() {
  const y=calDate.getFullYear(), m=calDate.getMonth();
  const lbl=calDate.toLocaleString('pt-BR',{month:'long',year:'numeric'});
  document.getElementById('cal-lbl').textContent=lbl.charAt(0).toUpperCase()+lbl.slice(1);
  const days=['Dom','Seg','Ter','Qua','Qui','Sex','Sáb'];
  document.getElementById('cal-heads').innerHTML=days.map(d=>`<div class="cal-dh">${d}</div>`).join('');
  const first=new Date(y,m,1).getDay(), last=new Date(y,m+1,0).getDate();
  const today=todayStr();
  const dates=new Set(load(K.P).filter(p=>p.status!=='Cancelado').map(p=>p.dataEntrega));
  let h='';
  for(let i=0;i<first;i++) h+=`<div class="cal-day other"></div>`;
  for(let d=1;d<=last;d++){
    const ds=`${y}-${String(m+1).padStart(2,'0')}-${String(d).padStart(2,'0')}`;
    h+=`<div class="cal-day${ds===today?' today':''}${dates.has(ds)?' has-ev':''}" onclick="calDayTap('${ds}')">${d}</div>`;
  }
  document.getElementById('cal-grid').innerHTML=h;
}
function calNav(d){ calDate.setMonth(calDate.getMonth()+d); renderCalendar(); }
function calDayTap(ds){
  const ps=load(K.P).filter(p=>p.dataEntrega===ds&&p.status!=='Cancelado');
  if(!ps.length) return;
  showToast(`${formatDate(ds)}: ${ps.length} entrega(s)`);
}
function setAgendaTab(el){
  document.querySelectorAll('#screen-agenda .tab').forEach(t=>t.classList.remove('active'));
  el.classList.add('active'); agendaTab=el.dataset.tab; renderAgendaList(agendaTab);
}
function renderAgendaList(tab){
  const ps=load(K.P);
  const t=todayStr(), a=offsetDate(1), d7=offsetDate(7), d30=offsetDate(30);
  let list=[];
  if(tab==='hoje')      list=ps.filter(p=>p.dataEntrega===t&&active(p));
  else if(tab==='amanha')   list=ps.filter(p=>p.dataEntrega===a&&active(p));
  else if(tab==='semana')   list=ps.filter(p=>p.dataEntrega>=t&&p.dataEntrega<=d7&&active(p));
  else if(tab==='mes')      list=ps.filter(p=>p.dataEntrega>=t&&p.dataEntrega<=d30&&active(p));
  else if(tab==='atrasados')list=ps.filter(isAtrasado);
  list.sort(sortByDate);
  document.getElementById('agenda-list').innerHTML=list.length?list.map(p=>pedidoCardHTML(p)).join(''):emptyHTML('Nenhuma entrega neste período.');
}
function renderFinanceiro(){
  const{rec,gasto,pend}=calcFin();
  document.getElementById('fin-rec').textContent   =fmtM(rec);
  document.getElementById('fin-gasto').textContent =fmtM(gasto);
  document.getElementById('fin-lucro').textContent =fmtM(rec-gasto);
  document.getElementById('fin-pend').textContent  =fmtM(pend);
  renderFinList(finTab);
}
function setFinTab(el){
  document.querySelectorAll('#screen-financeiro .tab').forEach(t=>t.classList.remove('active'));
  el.classList.add('active'); finTab=el.dataset.tab; renderFinanceiro();
}
function toggleFinAno(tipo, ano){
  const set = tipo==='receitas' ? finReceitasExpandido : finDespesasExpandido;
  if(set.has(ano)) set.delete(ano); else set.add(ano);
  renderFinList(finTab);
}
function renderPilhaReceitas(ano, itens){
  const isOpen = finReceitasExpandido.has(ano);
  const total = itens.reduce((s,r)=>s+(r.valor||0),0);
  const ordenados = [...itens].sort((a,b)=>b.data.localeCompare(a.data));
  return `
    <div class="card" style="padding:0;margin-bottom:10px;overflow:hidden">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;cursor:pointer" onclick="toggleFinAno('receitas','${ano}')">
        <div style="display:flex;align-items:center;gap:10px">
          <span style="font-family:var(--font-display);font-size:18px;font-weight:600">${isOpen?'▾':'▸'} ${ano}</span>
          <span style="font-size:12px;color:var(--text-soft)">${itens.length} receita${itens.length===1?'':'s'} · ${fmtM(total)}</span>
        </div>
        <span style="font-size:12px;color:var(--text-soft)">${isOpen?'recolher':'expandir'}</span>
      </div>
      ${isOpen?`<div style="border-top:1px solid var(--border-light);padding:0 20px">
        ${ordenados.map(r=>`
          <div class="tx-row">
            <div class="tx-left">
              <div class="tx-dot in"><svg viewBox="0 0 24 24"><polyline points="23 6 13.5 15.5 8.5 10.5 1 18"/><polyline points="17 6 23 6 23 12"/></svg></div>
              <div><div class="tx-desc">${r.ref||'Receita'}</div><div class="tx-date">${formatDate(r.data)}${r.cliente?' · '+r.cliente:''}</div></div>
            </div>
            <div style="text-align:right">
              <div class="tx-amount in">+${fmtM(r.valor)}</div>
              <button class="btn btn-ghost btn-sm" style="padding:4px 8px;margin-top:4px;font-size:11px" onclick="delReceita('${r.id}')">Remover</button>
            </div>
          </div>`).join('')}
      </div>`:''}
    </div>`;
}
function renderPilhaDespesas(ano, itens){
  const isOpen = finDespesasExpandido.has(ano);
  const total = itens.reduce((s,d)=>s+(d.valor||0),0);
  const ordenados = [...itens].sort((a,b)=>b.data.localeCompare(a.data));
  return `
    <div class="card" style="padding:0;margin-bottom:10px;overflow:hidden">
      <div style="display:flex;align-items:center;justify-content:space-between;padding:14px 18px;cursor:pointer" onclick="toggleFinAno('despesas','${ano}')">
        <div style="display:flex;align-items:center;gap:10px">
          <span style="font-family:var(--font-display);font-size:18px;font-weight:600">${isOpen?'▾':'▸'} ${ano}</span>
          <span style="font-size:12px;color:var(--text-soft)">${itens.length} despesa${itens.length===1?'':'s'} · ${fmtM(total)}</span>
        </div>
        <span style="font-size:12px;color:var(--text-soft)">${isOpen?'recolher':'expandir'}</span>
      </div>
      ${isOpen?`<div style="border-top:1px solid var(--border-light);padding:0 20px">
        ${ordenados.map(d=>`
          <div class="tx-row">
            <div class="tx-left">
              <div class="tx-dot out"><svg viewBox="0 0 24 24"><polyline points="23 18 13.5 8.5 8.5 13.5 1 6"/><polyline points="17 18 23 18 23 12"/></svg></div>
              <div><div class="tx-desc">${d.desc}</div><div class="tx-date">${formatDate(d.data)} · ${d.cat}</div></div>
            </div>
            <div style="text-align:right">
              <div class="tx-amount out">-${fmtM(d.valor)}</div>
              <button class="btn btn-ghost btn-sm" style="padding:4px 8px;margin-top:4px;font-size:11px" onclick="delDespesa('${d.id}')">Remover</button>
            </div>
          </div>`).join('')}
      </div>`:''}
    </div>`;
}
function renderFinList(tab){
  const el=document.getElementById('fin-list');
  if(tab==='receitas'){
    const rs=load(K.R);
    if(!rs.length){el.innerHTML=`<div class="card">${emptyHTML('Nenhuma receita registrada.')}</div>`;return;}
    const porAno = agruparPorAno(rs);
    const anos = Object.keys(porAno).sort().reverse();
    el.innerHTML = anos.map(ano=>renderPilhaReceitas(ano, porAno[ano])).join('');
  } else if(tab==='despesas'){
    const ds=load(K.D);
    if(!ds.length){el.innerHTML=`<div class="card">${emptyHTML('Nenhuma despesa registrada.')}</div>`;return;}
    const porAno = agruparPorAno(ds);
    const anos = Object.keys(porAno).sort().reverse();
    el.innerHTML = anos.map(ano=>renderPilhaDespesas(ano, porAno[ano])).join('');
  } else if(tab==='lucratividade'){
    el.innerHTML = renderLucratividade();
  } else if(tab==='estoque'){
    el.innerHTML = renderRelatorioEstoque();
  } else {
    const ps=load(K.P).filter(p=>p.pendente>0&&p.status!=='Cancelado').sort(sortByDate);
    if(!ps.length){el.innerHTML=`<div class="card">${emptyHTML('Nenhum pagamento pendente.')}</div>`;return;}
    el.innerHTML=`<div class="card">${ps.map(p=>{
      const wa = p.whatsapp ? `https://wa.me/55${p.whatsapp.replace(/\D/g,'')}` : null;
      return `
      <div class="tx-row" onclick="openDetail('${p.id}')" style="cursor:pointer">
        <div class="tx-left">
          <div class="tx-dot out"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg></div>
          <div><div class="tx-desc">${p.nome}</div><div class="tx-date">Entrega: ${p.dataEntrega?formatDate(p.dataEntrega):'—'}</div></div>
        </div>
        <div style="display:flex;align-items:center;gap:10px">
          <div style="text-align:right">
            <div class="tx-amount out">${fmtM(p.pendente)}</div>
            <div style="font-size:11px;color:var(--text-soft)">de ${fmtM(p.total)}</div>
          </div>
          ${wa?`<button class="btn-icon-wa" onclick="event.stopPropagation();window.open('${wa}','_blank')" title="WhatsApp">
            <svg viewBox="0 0 24 24" width="13" height="13" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 11.5a8.38 8.38 0 0 1-.9 3.8 8.5 8.5 0 0 1-7.6 4.7 8.38 8.38 0 0 1-3.8-.9L3 21l1.9-5.7a8.38 8.38 0 0 1-.9-3.8 8.5 8.5 0 0 1 4.7-7.6 8.38 8.38 0 0 1 3.8-.9h.5a8.48 8.48 0 0 1 8 8v.5z"/></svg>
          </button>`:''}
        </div>
      </div>`;
    }).join('')}</div>`;
  }
}
function renderLucratividade(){
  const ps = load(K.P).filter(p=>p.status!=='Cancelado' && (p.total||0)>0);
  if (!ps.length) return `<div class="card">${emptyHTML('Nenhum pedido com valor registrado ainda.<br><strong>Cadastre itens do catálogo e outros custos nos pedidos para ver a lucratividade real.</strong>')}</div>`;

  let totalVenda=0, totalPago=0, totalMat=0, totalExtras=0, totalLucro=0;
  const linhas = ps.map(p=>{
    const c = calcLucroPedido(p);
    totalVenda  += p.total||0;
    totalPago   += p.pago||0;
    totalMat    += c.custoMateriais;
    totalExtras += c.custoExtras;
    totalLucro  += c.lucroBruto;
    return { p, c };
  }).sort((a,b)=>(b.p.dataEntrega||'').localeCompare(a.p.dataEntrega||''));
  const margemMedia = totalVenda>0 ? (totalLucro/totalVenda*100) : 0;
  const totalVendasAvulsas = load(K.V).reduce((s,v)=>s+(v.valor||0),0);

  return `
  <div class="fin-grid">
    <div class="fin-tile"><div class="fin-tile-label">Vendido (pedidos)</div><div class="fin-tile-value blue">${fmtM(totalVenda)}</div></div>
    <div class="fin-tile"><div class="fin-tile-label">Custo materiais</div><div class="fin-tile-value red">${fmtM(totalMat)}</div></div>
    <div class="fin-tile"><div class="fin-tile-label">Outros custos</div><div class="fin-tile-value red">${fmtM(totalExtras)}</div></div>
    <div class="fin-tile"><div class="fin-tile-label">Lucro bruto</div><div class="fin-tile-value green">${fmtM(totalLucro)}</div></div>
  </div>
  <div class="card" style="text-align:center">
    <div class="card-label" style="justify-content:center">Margem de lucro média</div>
    <div style="font-family:var(--font-display);font-size:32px;font-weight:600;color:${margemMedia>=0?'var(--success)':'var(--danger)'}">${margemMedia.toFixed(1)}%</div>
    <div style="font-size:11px;color:var(--text-soft);margin-top:2px">Baseado em ${linhas.length} pedido${linhas.length===1?'':'s'} com valor registrado</div>
  </div>
  ${totalVendasAvulsas>0?`<div class="card" style="background:var(--blue-pale);border:none;box-shadow:none">
    <div style="font-size:12px;color:var(--text-mid);line-height:1.6">💡 Há <b>${fmtM(totalVendasAvulsas)}</b> em vendas avulsas registradas (aba Vendas). Elas entram no faturamento total do Financeiro, mas não aparecem no detalhamento acima porque não têm materiais/custos vinculados.</div>
  </div>`:''}

  <div class="card-label" style="margin:18px 4px 8px">Lucro por pedido</div>
  ${linhas.map(({p,c})=>`
    <div class="pedido-card" style="cursor:pointer" onclick="openDetail('${p.id}')">
      <div class="pedido-card-header">
        <div>
          <div class="pedido-nome">${p.nome||'—'}</div>
          <div class="pedido-sub">${p.dataEntrega?formatDate(p.dataEntrega):'—'}${p.produtos?' · '+(p.produtos.length>30?p.produtos.slice(0,30)+'…':p.produtos):''}</div>
        </div>
        <span class="badge" style="background:${c.margem>=0?'#E8F8EF':'var(--rose-pale)'};color:${c.margem>=0?'#1F9C5C':'var(--rose-dark)'};border-color:${c.margem>=0?'#A9E8C6':'var(--rose-light)'}">${c.margem.toFixed(0)}% margem</span>
      </div>
      <div class="detail-row"><span class="detail-key">Valor pago</span><span class="detail-val" style="color:var(--success)">${fmtM(p.pago)}</span></div>
      <div class="detail-row"><span class="detail-key">Custo materiais</span><span class="detail-val">${fmtM(c.custoMateriais)}</span></div>
      <div class="detail-row"><span class="detail-key">Outros custos</span><span class="detail-val">${fmtM(c.custoExtras)}</span></div>
      <div class="detail-row"><span class="detail-key">Lucro bruto</span><span class="detail-val" style="color:${c.lucroBruto>=0?'var(--success)':'var(--danger)'};font-weight:700">${fmtM(c.lucroBruto)}</span></div>
    </div>
  `).join('')}
  `;
}
function saveReceita(){
  const valor=parseFloat(document.getElementById('r-valor').value);
  const data=document.getElementById('r-data').value;
  if(!valor||!data){showToast('Preencha data e valor');return;}
  const rs=load(K.R);
  rs.push({id:'r'+Date.now(),data,cliente:document.getElementById('r-cliente').value,valor,ref:document.getElementById('r-ref').value});
  save(K.R,rs); closeModal('modal-receita'); renderFinanceiro(); showToast('Receita salva.');
}
function saveDespesa(){
  const valor=parseFloat(document.getElementById('d-valor').value);
  const data=document.getElementById('d-data').value;
  const desc=document.getElementById('d-desc').value.trim();
  if(!valor||!data||!desc){showToast('Preencha todos os campos');return;}
  const ds=load(K.D);
  ds.push({id:'d'+Date.now(),data,desc,cat:document.getElementById('d-cat').value,valor});
  save(K.D,ds); closeModal('modal-despesa'); renderFinanceiro(); showToast('Despesa salva.');
}
function delReceita(id){if(!confirm('Remover?'))return;fbDel('receitas',id);save(K.R,load(K.R).filter(r=>r.id!==id));renderFinanceiro();}
function delDespesa(id){if(!confirm('Remover?'))return;fbDel('despesas',id);save(K.D,load(K.D).filter(d=>d.id!==id));renderFinanceiro();}
/* ── VENDAS ──────────────────────────────────────── */
function renderVendas(){ renderVendasContent(vendasTab); }
function setVendasTab(el){
  document.querySelectorAll('#screen-vendas .tab').forEach(t=>t.classList.remove('active'));
  el.classList.add('active'); vendasTab=el.dataset.tab; renderVendasContent(vendasTab);
}
function renderVendasContent(tab){
  const el=document.getElementById('vendas-content');
  if(tab==='historico'){
    const vs=load(K.V).sort((a,b)=>b.data.localeCompare(a.data));
    if(!vs.length){el.innerHTML=emptyHTML('Nenhuma venda registrada.');return;}
    el.innerHTML='<div class="card">'+vs.map(v=>`
      <div class="tx-row">
        <div class="tx-left">
          <div class="tx-dot in"><svg viewBox="0 0 24 24"><path d="M6 2L3 6v14a2 2 0 0 0 2 2h14a2 2 0 0 0 2-2V6l-3-4z"/><line x1="3" y1="6" x2="21" y2="6"/><path d="M16 10a4 4 0 0 1-8 0"/></svg></div>
          <div><div class="tx-desc">${v.produto}</div><div class="tx-date">${formatDate(v.data)}${v.cliente?' · '+v.cliente:''} · Qtd: ${v.qtd}</div></div>
        </div>
        <div style="text-align:right">
          <div class="tx-amount in">${fmtM(v.valor)}</div>
          <button class="btn btn-ghost btn-sm" style="padding:4px 8px;margin-top:4px;font-size:11px" onclick="delVenda('${v.id}')">Remover</button>
        </div>
      </div>`).join('')+'</div>';
  } else {
    el.innerHTML=`<div class="card" style="text-align:center;padding:36px 20px">
      <div style="font-family:var(--font-display);font-size:36px;color:var(--blue-light);margin-bottom:14px">Venda Avulsa</div>
      <p style="font-size:13px;color:var(--text-soft);margin-bottom:20px">Registre uma venda sem pedido formal</p>
      <button class="btn btn-primary" onclick="openVendaModal()">Registrar venda</button>
    </div>`;
  }
}
function openVendaModal(){
  ['venda-id','v-cliente','v-produto-manual','v-valor'].forEach(id=>document.getElementById(id).value='');
  document.getElementById('v-data').value=todayStr();
  document.getElementById('v-qtd').value=1;
  populateProdutoSelectVenda();
  openModal('modal-venda');
}
function populateProdutoSelectVenda(selectedId){
  const prods = load(K.PR).filter(p=>p.status!=='Inativo');
  const sel = document.getElementById('v-produto-select');
  sel.innerHTML = (prods.length ? prods.map(p=>`<option value="${p.id}">${p.nome} (${fmtM(p.preco)})</option>`).join('') : '')
    + '<option value="__manual__">✏️ Outro (digitar manualmente)</option>';
  sel.value = selectedId || (prods.length ? prods[0].id : '__manual__');
  onVendaProdutoChange();
}
function onVendaProdutoChange(){
  const sel = document.getElementById('v-produto-select');
  const manualWrap = document.getElementById('v-produto-manual-wrap');
  if (!sel) return;
  if (sel.value === '__manual__'){
    manualWrap.style.display = 'block';
  } else {
    manualWrap.style.display = 'none';
    const prod = load(K.PR).find(p=>p.id===sel.value);
    if (prod){
      const qtd = parseFloat(document.getElementById('v-qtd').value)||1;
      document.getElementById('v-valor').value = (prod.preco*qtd).toFixed(2);
    }
  }
}
function saveVenda(){
  const sel = document.getElementById('v-produto-select');
  let prod = '';
  if (sel.value === '__manual__') prod = document.getElementById('v-produto-manual').value.trim();
  else { const p = load(K.PR).find(x=>x.id===sel.value); prod = p ? p.nome : ''; }
  if(!prod){showToast('Informe o produto');return;}
  const vs=load(K.V);
  vs.push({id:'v'+Date.now(),cliente:document.getElementById('v-cliente').value,produto:prod,qtd:parseInt(document.getElementById('v-qtd').value)||1,valor:parseFloat(document.getElementById('v-valor').value)||0,data:document.getElementById('v-data').value});
  save(K.V,vs); closeModal('modal-venda'); renderVendas(); showToast('Venda registrada.');
}
function delVenda(id){if(!confirm('Remover?'))return;fbDel('vendas',id);save(K.V,load(K.V).filter(v=>v.id!==id));renderVendas();}
/* ── VERSE / CONFIG ──────────────────────────────── */
function applyVerse(){
  appConfig=loadO(K.C);
  const v=appConfig.verse||{text:'Tudo o que fizerem, façam de todo o coração, como para o Senhor...',ref:'Colossenses 3:23'};
  document.getElementById('verse-text').textContent=v.text;
  document.getElementById('verse-ref').textContent=v.ref;
}
function showVerseConfig(){
  appConfig=loadO(K.C);
  const v=appConfig.verse||{};
  document.getElementById('verse-edit-text').value=v.text||'';
  document.getElementById('verse-edit-ref').value=v.ref||'';
  openModal('modal-verse');
}
function saveVerse(){
  appConfig=loadO(K.C);
  appConfig.verse={text:document.getElementById('verse-edit-text').value,ref:document.getElementById('verse-edit-ref').value};
  save(K.C,appConfig); closeModal('modal-verse'); applyVerse(); showToast('Versículo atualizado.');
}
function showProfileConfig(){
  document.getElementById('perfil-senha-atual').value = '';
  document.getElementById('perfil-senha-nova').value = '';
  document.getElementById('perfil-senha-conf').value = '';
  openModal('modal-perfil');
}
function savePerfil(){
  const senhaAt  = document.getElementById('perfil-senha-atual').value;
  const senhaNova= document.getElementById('perfil-senha-nova').value;
  const senhaConf= document.getElementById('perfil-senha-conf').value;

  // Verificar senha atual (contra o valor persistido, não a constante fixa)
  if (!senhaAt) { showToast('Informe a senha atual'); return; }
  if (senhaAt !== getSenhaAtual()) { showToast('Senha atual incorreta'); return; }

  if (senhaNova) {
    if (senhaNova !== senhaConf) { showToast('As senhas não coincidem'); return; }
    if (senhaNova.length < 4)    { showToast('Senha muito curta (mín. 4 caracteres)'); return; }
    appConfig = loadO(K.C);
    appConfig.senhaCustom = senhaNova;
    save(K.C, appConfig);
  }

  closeModal('modal-perfil');
  showToast('Senha atualizada com sucesso!');
}
