function testNotification(){
  if(!('Notification'in window)){showToast('Notificações não suportadas');return;}
  Notification.requestPermission().then(p=>{
    if(p==='granted'){new Notification('Graça em Papel',{body:'Notificações ativadas!'}); showToast('Notificações ativadas.');}
    else showToast('Permissão negada.');
  });
}
/* ── FAB ─────────────────────────────────────────── */
function handleFab(){
  if(currentScreen==='financeiro'){
    if(finTab==='receitas'){document.getElementById('r-data').value=todayStr();openModal('modal-receita');}
    else if(finTab==='despesas'){document.getElementById('d-data').value=todayStr();openModal('modal-despesa');}
    else openPedidoModal();
  } else if(currentScreen==='vendas'){openVendaModal();}
  else if(currentScreen==='produtos'){ openProdutoModal(); }
  else if(currentScreen==='estoque'){ openMaterialModal(); }
  else if(currentScreen==='clientes'){ openClienteFormModal(); }
  else openPedidoModal();
}
/* ── PUSH NOTIFICATIONS ──────────────────────────── */
function schedulePush(){
  checkPush();
  setInterval(checkPush,3600000);
}
function checkPush(){
  if(!('Notification'in window)||Notification.permission!=='granted')return;
  const today=todayStr(),amanha=offsetDate(1),d3=offsetDate(3),d7=offsetDate(7);
  load(K.P).forEach(p=>{
    if(p.status==='Entregue'||p.status==='Cancelado'||!p.dataEntrega)return;
    const de=p.dataEntrega;
    if(de===today) new Notification('Graça em Papel · Entrega hoje',{body:p.nome});
    else if(de===amanha) new Notification('Graça em Papel · Entrega amanhã',{body:p.nome});
    else if(de===d3) new Notification('Graça em Papel · 3 dias',{body:`Entrega de ${p.nome} em 3 dias`});
    else if(de<today) new Notification('Graça em Papel · Atrasado',{body:`${p.nome} — ${diasAtraso(p)}d de atraso`});
  });
}
/* ── MODAL UTILS ─────────────────────────────────── */
let _modalZ = 1000;
function openModal(id){
  const el = document.getElementById(id);
  _modalZ += 1;
  el.style.zIndex = _modalZ;
  el.classList.add('active');
}
function closeModal(id){ document.getElementById(id).classList.remove('active'); }
document.querySelectorAll('.modal-overlay').forEach(o=>{
  o.addEventListener('click',e=>{ if(e.target===o) o.classList.remove('active'); });
});
function emptyHTML(msg){
  return`<div class="empty"><div class="empty-icon"><svg viewBox="0 0 24 24"><circle cx="12" cy="12" r="10"/><path d="M8 15s1.5 2 4 2 4-2 4-2"/><line x1="9" y1="9" x2="9.01" y2="9"/><line x1="15" y1="9" x2="15.01" y2="9"/></svg></div><p>${msg}</p></div>`;
}
function showToast(msg){
  document.querySelectorAll('.toast').forEach(t=>t.remove());
  const t=document.createElement('div');t.className='toast';t.textContent=msg;
  document.body.appendChild(t);setTimeout(()=>t.remove(),2700);
}
/* ── PWA ─────────────────────────────────────────── */
let deferredPrompt;
window.addEventListener('beforeinstallprompt',e=>{
  e.preventDefault();deferredPrompt=e;
  document.getElementById('install-btn').style.display='inline-flex';
});
function installPWA(){
  if(deferredPrompt){deferredPrompt.prompt();deferredPrompt.userChoice.then(()=>{deferredPrompt=null;});}
}
// Service Worker removido — evita cache que causava login automático indevido
const mf={
  name:'Graça em Papel · Central de Gestão',
  short_name:'Graça em Papel',
  description:'Central de gestão de pedidos, clientes, financeiro e estoque da Graça em Papel.',
  start_url:'./',
  scope:'./',
  id:'/',
  display:'standalone',
  orientation:'portrait',
  background_color:'#FFF8F2',
  theme_color:'#2C7FB0',
  icons:[
    {src:"data:image/png;base64,",sizes:'192x192',type:'image/png',purpose:'any'},
    {src:"data:image/png;base64,",sizes:'512x512',type:'image/png',purpose:'any'},
    {src:"data:image/png;base64,",sizes:'192x192',type:'image/png',purpose:'maskable'},
    {src:"data:image/png;base64,",sizes:'512x512',type:'image/png',purpose:'maskable'}
  ]
};
document.getElementById('manifest-link').href=URL.createObjectURL(new Blob([JSON.stringify(mf)],{type:'application/json'}));

/* ── INIT ────────────────────────────────────────── */
window.addEventListener('DOMContentLoaded', () => {
  applyVerse();
  // Só abre o app se esta sessão de navegador fez login (K.U salvo localmente)
  const session = loadO(K.U);
  if (session?.email) {
    // Já estava logado neste navegador — sincroniza e abre
    const doSync = () => {
      if (window.fbSyncOnBoot) {
        window.fbSyncOnBoot().then(() => { initDemo(); bootApp(); }).catch(() => { initDemo(); bootApp(); });
      } else {
        initDemo(); bootApp();
      }
    };
    if (window.FB?.ready) { doSync(); }
    else {
      window.addEventListener('fb-ready', doSync, { once: true });
      setTimeout(doSync, 4000);
    }
  }
  // Se não tem sessão, fica na tela de login — não faz nada
});
